INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775006086746', 'A company is developing a new web application where users will sign up and log in. After successful authentication, these users need to securely upload and retrieve files from an Amazon S3 bucket. The development team needs to implement a solution that handles user authentication and then grants temporary, limited-privilege access to AWS resources for these authenticated users. Which combination of AWS services should the developer use to meet these requirements with the LEAST operational overhead?', '["Use Amazon Cognito User Pools for user authentication and Amazon Cognito Identity Pools to vend temporary AWS credentials for S3 access.","Use Amazon Cognito User Pools for both user authentication and directly grant S3 access based on User Pool groups.","Create individual AWS IAM users for each application user and manage their credentials for S3 access.","Implement a custom authentication service on an Amazon EC2 instance and use AWS IAM roles for S3 access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages Amazon Cognito User Pools for managing user sign-up and sign-in, which provides JWT tokens. Amazon Cognito Identity Pools then exchange these tokens for temporary, limited-privilege AWS IAM credentials, allowing authenticated users to securely access AWS services like Amazon S3 without exposing long-term credentials. This approach is fully managed and has low operational overhead. Option B (incorrect) confuses the distinct purposes of User Pools and Identity Pools; User Pools handle application-level authentication, while Identity Pools vend AWS credentials. User Pools alone cannot directly grant temporary AWS resource access. Option C (incorrect) is an anti-pattern (ap-2.1-002) as it involves creating and managing individual IAM users for application users, which is not scalable, secure, or practical for a large user base. Option D (incorrect) introduces significant operational overhead by requiring a custom authentication service on an EC2 instance, which would involve managing servers, scaling, and security patches, contrary to the ''LEAST operational overhead'' constraint.', 29, 'm_29_1', 1, NULL, NULL),
  ('mock_28_all_1775006086746', 'A mobile application uses an Amazon API Gateway REST API to interact with backend AWS Lambda functions. The application requires a custom authorization mechanism where user tokens are validated by a separate microservice before allowing access to API resources. The development team wants to implement this authorization with the LEAST operational overhead. Which API Gateway authorization option should they choose?', '["Use IAM authorization for the API Gateway, requiring clients to sign requests with AWS credentials.","Implement an AWS Lambda authorizer to validate custom tokens before invoking the backend Lambda function.","Configure Amazon Cognito User Pool authorizers, integrating directly with the custom authentication microservice.","Perform custom token validation logic within each backend AWS Lambda function that the API Gateway invokes."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable choice for custom authorization logic with the least operational overhead. An AWS Lambda authorizer (formerly custom authorizer) allows you to implement custom logic to validate bearer tokens (like JWTs or OAuth tokens) and return an IAM policy that authorizes the request. This is a fully managed service, reducing operational burden. Option A (incorrect) is not suitable for custom token validation as IAM authorization relies on AWS IAM credentials, not custom tokens. Option C (incorrect) would be appropriate if Amazon Cognito User Pools were used for authentication, but the scenario specifies a ''custom authorization mechanism'' and a ''separate microservice'' for validation, which doesn''t directly align with Cognito User Pool authorizers. Option D (incorrect) would increase operational overhead significantly because the authorization logic would need to be duplicated and maintained across multiple backend Lambda functions, violating the ''LEAST operational overhead'' constraint.', 29, 'm_29_1', 2, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is building an AWS Lambda function that needs to read and write data to an Amazon DynamoDB table. The function must be able to access the DynamoDB table securely and follow AWS best practices for credential management. Which approach should the developer implement to grant the Lambda function the necessary permissions?', '["Embed AWS IAM access keys directly into the Lambda function''s environment variables.","Store the IAM access keys in AWS Systems Manager Parameter Store SecureString and retrieve them in the Lambda function code.","Create an AWS IAM role with the necessary DynamoDB permissions and assign it to the Lambda function.","Use Amazon Cognito Identity Pools to generate temporary credentials for the Lambda function."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS best practice for granting permissions to compute services like AWS Lambda. By assigning an AWS IAM role to the Lambda function, the function automatically receives temporary credentials, eliminating the need to manage or hardcode credentials. This adheres to the principle of least privilege and reduces security risks. Option A (incorrect) is an anti-pattern (ap-2.1-002) because hardcoding IAM access keys in environment variables or code is insecure and risks exposure. Option B (incorrect) is also an anti-pattern (ap-2.1-002) as storing IAM access keys in Parameter Store, while encrypted, still requires the Lambda function to retrieve and manage these static credentials, which is less secure and less manageable than using an IAM role. Option D (incorrect) is not designed for granting permissions to AWS services like Lambda functions; Amazon Cognito Identity Pools are primarily used to vend temporary AWS credentials to end-users of mobile and web applications.', 29, 'm_29_1', 3, NULL, NULL),
  ('mock_28_all_1775006086746', 'A development team needs to deploy an AWS Lambda function in Account A that must perform administrative actions on Amazon S3 buckets located in Account B. The solution must ensure secure, temporary, and auditable cross-account access without sharing long-term credentials. Which AWS service should be used to facilitate this cross-account interaction?', '["Create an IAM user in Account B with administrative S3 permissions and share its access keys with Account A''s Lambda function.","Configure an Amazon Cognito Identity Pool in Account A to generate temporary credentials for the Lambda function to access Account B.","Hardcode the access keys of an IAM user from Account B directly into the Lambda function''s environment variables in Account A.","Utilize AWS Security Token Service (STS) `AssumeRole` in Account A to assume an IAM role defined in Account B with S3 permissions."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the AWS best practice for secure cross-account access. The AWS Security Token Service (STS) `AssumeRole` operation allows an IAM principal in one account (like a Lambda function with an associated IAM role in Account A) to temporarily assume an IAM role in another account (Account B). This provides temporary, limited-privilege credentials, ensuring security and auditability without sharing long-term access keys. Option A (incorrect) is an anti-pattern (ap-2.1-002) as sharing IAM user access keys between accounts is highly insecure and violates the principle of least privilege and temporary credentials. Option B (incorrect) is not the correct service for service-to-service cross-account access; Amazon Cognito Identity Pools are designed for end-user authentication and authorization to AWS resources. Option C (incorrect) is a severe anti-pattern (ap-2.1-002) as hardcoding credentials directly into application code or environment variables is a major security risk.', 29, 'm_29_1', 4, NULL, NULL),
  ('mock_28_all_1775006086746', 'A startup is building a new mobile application and requires a fully managed service for user registration, login, and multi-factor authentication. The application needs to support standard authentication protocols and issue JSON Web Tokens (JWTs) for authenticated users. The team wants a solution that minimizes the effort of managing user directories and authentication flows. Which AWS service should they choose?', '["Amazon Cognito User Pools.","AWS IAM users and groups.","AWS Directory Service.","A custom authentication server hosted on Amazon EC2."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal service for this scenario. Amazon Cognito User Pools provide a fully managed user directory service that handles user registration, login, and multi-factor authentication. It supports standard authentication protocols (OAuth 2.0, OIDC) and issues JWTs, perfectly aligning with the requirements for a mobile application''s user authentication with minimal management effort. Option B (incorrect) is designed for managing access to AWS resources and services, not for application end-users. Creating IAM users for application users is an anti-pattern (ap-2.1-002) and not scalable. Option C (incorrect) is primarily for integrating with on-premises directories or providing managed Active Directory, not for public-facing application user authentication. Option D (incorrect) would introduce significant operational overhead, requiring the team to manage servers, security, scaling, and the entire authentication logic themselves, contrary to the goal of minimizing effort.', 29, 'm_29_1', 5, NULL, NULL),
  ('mock_28_all_1775006086746', 'An internal REST API, exposed via Amazon API Gateway, is exclusively consumed by other AWS Lambda functions within the same AWS account. The development team needs to ensure that only authorized Lambda functions can invoke specific API endpoints, with granular control over permissions. Which API Gateway authorization method provides the MOST secure and granular control for this service-to-service interaction?', '["Use Amazon Cognito User Pool authorizers to validate tokens issued by an internal identity provider.","Implement IAM authorization for the API Gateway, allowing specific IAM roles to invoke endpoints.","Use AWS Lambda authorizers to perform custom authorization logic based on request headers.","Configure no authorization on the API Gateway and rely on VPC endpoint policies for access control."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most secure and granular approach for service-to-service authorization within AWS. IAM authorization for API Gateway allows you to define precise permissions using IAM policies attached to the invoking Lambda functions'' execution roles. This leverages AWS''s native identity and access management system, providing fine-grained control and auditability. Option A (incorrect) is designed for human users authenticating via Cognito User Pools, not for service-to-service authentication between AWS Lambda functions. Option C (incorrect) would introduce unnecessary operational overhead for a straightforward service-to-service authorization use case that IAM can handle natively and more efficiently. Option D (incorrect) is highly insecure as it leaves the API Gateway publicly accessible without any authorization layer, which is a significant security vulnerability, even if network controls are in place.', 29, 'm_29_1', 6, NULL, NULL),
  ('mock_28_all_1775006086746', 'An application running on an Amazon EC2 instance needs to securely access data stored in an Amazon S3 bucket. The development team wants to ensure that the EC2 instance has the necessary permissions without embedding any credentials directly into the application code or configuration files. Which is the most secure and recommended method to grant S3 access to the EC2 instance?', '["Store the IAM user access keys in an encrypted file on the EC2 instance and retrieve them using the application code.","Hardcode the IAM user access keys directly into the application''s configuration file on the EC2 instance.","Attach an AWS IAM role with the required S3 permissions to the EC2 instance.","Use AWS Systems Manager Parameter Store to store the IAM user access keys as SecureString and retrieve them from the EC2 instance."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS best practice for granting permissions to Amazon EC2 instances. By attaching an AWS IAM role to the EC2 instance, the instance automatically receives temporary credentials from the EC2 instance metadata service. This eliminates the need to hardcode or manage credentials within the application or on the instance itself, significantly enhancing security and reducing operational overhead. Option A (incorrect) and Option D (incorrect) are both less secure than using IAM roles. While they involve encryption or secure storage, they still require the application to handle static credentials, which is an anti-pattern (ap-2.1-002). Option B (incorrect) is a severe anti-pattern (ap-2.1-002) as hardcoding credentials directly into configuration files is highly insecure and risks exposure.', 29, 'm_29_1', 7, NULL, NULL);

