-- Module: m_29_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775006086746', 'A company stores highly sensitive customer data in an Amazon S3 bucket. Compliance requirements mandate that all data must be encrypted at rest, and there must be an audit trail of key usage. The development team wants to achieve this with the LEAST operational overhead for key management. Which S3 encryption option should they choose?', '["Server-Side Encryption with Amazon S3-managed keys (SSE-S3).","Server-Side Encryption with Customer-Provided Keys (SSE-C).","Client-Side Encryption with a client-managed encryption key.","Server-Side Encryption with AWS Key Management Service (SSE-KMS)."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the best choice for meeting the requirements with the least operational overhead. SSE-KMS encrypts objects with keys managed by AWS KMS, providing an audit trail through AWS CloudTrail logs of when the KMS key was used. AWS KMS handles key rotation and management, significantly reducing operational overhead compared to client-managed keys. Option A (incorrect) provides encryption at rest but does not offer an audit trail of key usage in CloudTrail, which is a compliance requirement. Option B (incorrect) requires the customer to provide and manage their own encryption keys, which increases operational overhead for key management. Option C (incorrect) also places the burden of key management and encryption entirely on the client application, leading to higher operational overhead and potential for errors.', 29, 'm_29_2', 8, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is deploying a new public-facing REST API using Amazon API Gateway. All communication between clients and the API Gateway must be encrypted in transit to protect sensitive data. The developer needs to ensure that only secure connections are accepted. Which action should the developer take to enforce encryption in transit?', '["Configure the API Gateway to only accept requests over HTTPS/TLS 1.2 or higher.","Implement client-side encryption within the mobile application that consumes the API.","Deploy AWS WAF in front of API Gateway to block unencrypted HTTP traffic.","Use AWS Key Management Service (KMS) to encrypt the API Gateway''s configuration."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the requirement to enforce encryption in transit. Amazon API Gateway automatically provides HTTPS endpoints, and you can configure it to enforce a minimum TLS version, ensuring that all data exchanged between clients and the API Gateway is encrypted. This is a fundamental security control for APIs. Option B (incorrect) places the responsibility for encryption on the client application, which is not a reliable way to enforce encryption for all clients and doesn''t ensure the API Gateway itself only accepts secure connections. Option C (incorrect) is primarily a web application firewall used for protecting against common web exploits, not for enforcing encryption in transit at the protocol level. While it can block HTTP, it''s not its primary function for this specific requirement. Option D (incorrect) is for encryption at rest of API Gateway''s internal data, not for enforcing encryption of data in transit between clients and the API Gateway.', 29, 'm_29_2', 9, NULL, NULL),
  ('mock_28_all_1775006086746', 'An application needs to encrypt large files before uploading them to Amazon S3. The encryption process must utilize AWS Key Management Service (KMS) for key management, but the actual data encryption should happen client-side to avoid sending large data volumes to KMS. The solution should also minimize the number of KMS API calls. Which KMS operation is most appropriate for this scenario?', '["Use the AWS KMS `Encrypt` API operation to encrypt the entire file directly.","Use the AWS KMS `GenerateDataKey` API operation to obtain a data key and its encrypted copy.","Implement a custom client-side encryption library without using AWS KMS.","Configure Amazon S3 Server-Side Encryption with S3-managed keys (SSE-S3) for the bucket."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the ideal approach for client-side encryption of large files using AWS KMS. The `GenerateDataKey` operation returns a plaintext data key for client-side encryption and an encrypted copy of that data key. The plaintext key is used to encrypt the large file locally, and then the plaintext key is immediately discarded. The encrypted data key is stored alongside the encrypted file. This minimizes KMS API calls and avoids sending large files to KMS, which has size limits and higher costs. Option A (incorrect) is not suitable for large files due to KMS payload size limits and higher costs associated with encrypting large data directly. Option C (incorrect) would mean foregoing the benefits of centralized key management, auditing, and security provided by AWS KMS. Option D (incorrect) is a server-side encryption option, which does not meet the requirement for client-side encryption.', 29, 'm_29_2', 10, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is building an AWS Lambda function that connects to an Amazon RDS database. The database credentials (username and password) must be stored securely and automatically rotated every 90 days to comply with security policies. Which AWS service should the developer use to manage these credentials with the LEAST operational overhead?', '["Store the credentials as plaintext environment variables in the Lambda function.","Store the credentials in AWS Systems Manager Parameter Store as a SecureString.","Use AWS Secrets Manager to store and automatically rotate the database credentials.","Hardcode the database credentials directly into the Lambda function''s source code."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate service for this requirement. AWS Secrets Manager is specifically designed for storing, managing, and automatically rotating database credentials, API keys, and other secrets. It integrates with Amazon RDS to automate the rotation process, significantly reducing operational overhead. Option A (incorrect) is highly insecure as plaintext environment variables are easily exposed. Option B (incorrect) is an anti-pattern (ap-2.2-001) for secrets requiring rotation; while AWS Systems Manager Parameter Store SecureString encrypts secrets at rest, it does not support automatic rotation, requiring manual intervention. Option D (incorrect) is a severe anti-pattern (ap-2.1-002) as hardcoding credentials is a major security risk and makes rotation extremely difficult.', 29, 'm_29_2', 11, NULL, NULL),
  ('mock_28_all_1775006086746', 'A development team needs to store non-sensitive log files in an Amazon S3 bucket. The company''s policy requires all data at rest to be encrypted, but there are no specific requirements for key management or audit trails for these logs. The team wants the MOST cost-effective encryption solution with zero key management overhead. Which S3 encryption option should they choose?', '["Server-Side Encryption with AWS Key Management Service (SSE-KMS).","Server-Side Encryption with Customer-Provided Keys (SSE-C).","Client-Side Encryption with a client-managed encryption key.","Server-Side Encryption with Amazon S3-managed keys (SSE-S3)."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most cost-effective and lowest overhead solution for this scenario. SSE-S3 uses keys managed entirely by Amazon S3, providing encryption at rest with no additional cost beyond standard S3 storage and no key management responsibilities for the customer. Option A (incorrect) uses AWS KMS, which incurs additional costs for KMS key usage and API calls, making it less cost-effective than SSE-S3 when an audit trail is not required. Option B (incorrect) requires the customer to manage and provide their own encryption keys, increasing operational overhead and potentially cost. Option C (incorrect) involves implementing and managing client-side encryption, which adds significant development and operational overhead.', 29, 'm_29_2', 12, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer needs to encrypt and decrypt small, arbitrary pieces of sensitive configuration data within an application. The encryption keys must be centrally managed and auditable, and the process should be integrated with AWS services. Which AWS service and operation should the developer use for this task?', '["Use AWS Key Management Service (KMS) `Encrypt` and `Decrypt` API operations.","Implement a custom AES-256 encryption library within the application code.","Store the data as a SecureString in AWS Systems Manager Parameter Store.","Use AWS Secrets Manager to store the configuration data as a secret."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the appropriate choice. AWS KMS provides a managed service for creating and controlling encryption keys. The `Encrypt` and `Decrypt` API operations allow applications to directly encrypt and decrypt small data blobs (up to 4 KB) using KMS keys. This offers centralized key management, auditability via AWS CloudTrail, and strong security. Option B (incorrect) would require the developer to manage encryption keys, algorithms, and security best practices themselves, which is complex and prone to errors, lacking centralized management and auditability. Option C (incorrect) is for storing configuration parameters or secrets, not for direct, on-demand encryption/decryption of arbitrary data within an application''s logic. While it encrypts at rest, it''s not designed for the `Encrypt`/`Decrypt` functionality. Option D (incorrect) is primarily for managing credentials and secrets that often require rotation, not for general-purpose encryption/decryption of arbitrary data blobs within an application.', 29, 'm_29_2', 13, NULL, NULL),
  ('mock_28_all_1775006086746', 'A web application hosted on Amazon EC2 instances behind an Application Load Balancer (ALB) must ensure that all traffic between client browsers and the ALB is encrypted using HTTPS. The development team needs a solution that manages SSL/TLS certificates automatically. Which approach should be implemented to meet this requirement?', '["Configure the EC2 instances to handle SSL/TLS termination and redirect HTTP to HTTPS.","Configure the ALB listener to use HTTPS with a certificate provisioned by AWS Certificate Manager (ACM).","Implement AWS WAF rules to block all HTTP traffic at the edge.","Use a custom client-side encryption library within the web application to encrypt data before sending."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the recommended and most efficient approach. Configuring the ALB listener to use HTTPS with a certificate from AWS Certificate Manager (ACM) offloads SSL/TLS termination from the EC2 instances to the ALB. ACM provides free, automatically renewed SSL/TLS certificates, significantly reducing operational overhead for certificate management. Option A (incorrect) places the burden of SSL/TLS termination and certificate management on the EC2 instances, increasing their CPU utilization and operational complexity. Option C (incorrect) is a web application firewall that protects against common web exploits, not primarily for enforcing HTTPS encryption at the load balancer level. While it can block HTTP, it''s not the direct mechanism for TLS termination. Option D (incorrect) is not a standard or practical way to enforce HTTPS for a web application; client-side encryption is typically for specific data fields, not for the entire communication channel.', 29, 'm_29_2', 14, NULL, NULL);

