INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775006086746', 'An AWS Lambda function needs to access a third-party API key. This API key is sensitive and should be encrypted at rest, never hardcoded, and ideally support future rotation. The development team wants to manage this secret securely following AWS best practices. Which service should they use to store and retrieve the API key?', '["Store the API key directly in the Lambda function''s environment variables.","Hardcode the API key within the Lambda function''s source code.","Store the API key in AWS Secrets Manager and retrieve it at runtime using the AWS SDK.","Store the API key as a SecureString in AWS Systems Manager Parameter Store."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best practice for managing sensitive API keys. AWS Secrets Manager provides secure storage, encryption at rest, and the capability for automatic rotation, which is crucial for sensitive credentials. The Lambda function can retrieve the secret at runtime using the AWS SDK, ensuring no credentials are hardcoded. Option A (incorrect) stores the API key in environment variables, which are encrypted at rest by AWS KMS, but Secrets Manager offers more robust management features like rotation and fine-grained access control. Option B (incorrect) is a severe anti-pattern (ap-2.1-002) as hardcoding secrets directly into code is highly insecure and makes rotation extremely difficult. Option D (incorrect) is an anti-pattern (ap-2.2-001) for secrets requiring rotation; while AWS Systems Manager Parameter Store SecureString encrypts secrets at rest, it does not support automatic rotation, making it less suitable for sensitive API keys that should be rotated.', 29, 'm_29_3', 15, NULL, NULL),
  ('mock_28_all_1775006086746', 'A Lambda function processes user registration data, which includes Personally Identifiable Information (PII). During development and debugging, developers need to log information about the function''s execution, but strict compliance rules prohibit logging PII to Amazon CloudWatch Logs. Which approach should the developer take to meet both debugging and compliance requirements?', '["Disable all logging for the Lambda function to prevent any data exposure.","Encrypt the Amazon CloudWatch Logs group to protect all log data.","Configure IAM policies to restrict access to CloudWatch Logs for all developers.","Redact or mask all sensitive PII fields from log messages before sending them to CloudWatch Logs."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the appropriate solution. To prevent PII exposure while still allowing for debugging, the developer must explicitly redact or mask sensitive PII fields from log messages before they are sent to Amazon CloudWatch Logs. This ensures that only non-sensitive information is logged, satisfying compliance requirements without hindering debugging. Option A (incorrect) would prevent any debugging or monitoring, making it impossible to troubleshoot issues effectively. Option B (incorrect) encrypts the logs at rest in CloudWatch, but the PII would still be present in the logs before encryption, violating the compliance rule against logging PII (ap-2.3-001). Option C (incorrect) restricts access but does not prevent the PII from being logged in the first place, which is the core compliance violation.', 29, 'm_29_3', 16, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is building an AWS Lambda function that requires a static, encrypted configuration value, such as a third-party service endpoint URL or a feature flag. This value does not require automatic rotation but must be securely stored and easily retrieved by the Lambda function. Which AWS service should be used to manage this configuration parameter with minimal management overhead?', '["Store the value as a SecureString in AWS Systems Manager Parameter Store.","Store the value in AWS Secrets Manager.","Hardcode the value directly into the Lambda function''s environment variables.","Store the value in an encrypted Amazon S3 object."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable service for securely storing static, encrypted configuration values. AWS Systems Manager Parameter Store SecureString encrypts the parameter value using AWS KMS and allows easy retrieval by the Lambda function with appropriate IAM permissions. It''s ideal for non-rotating configuration data with minimal management overhead. Option B (incorrect) is overkill for a static, non-rotating configuration value. AWS Secrets Manager is designed for secrets that require frequent rotation and more advanced management features, incurring higher costs. Option C (incorrect) is less secure than Parameter Store as it''s not centrally managed and could be exposed if not handled carefully. While Lambda environment variables are encrypted at rest, Parameter Store offers a more robust and auditable solution for configuration. Option D (incorrect) is not designed for direct configuration retrieval by a Lambda function; it would require additional code to download and decrypt the object, adding unnecessary complexity.', 29, 'm_29_3', 17, NULL, NULL),
  ('mock_28_all_1775006086746', 'An Amazon S3 bucket contains highly sensitive data that must only be accessible from a specific range of IP addresses within the corporate network. The development team needs to implement a security control that restricts access to the bucket based on the source IP address of the request. Which AWS mechanism should be used to enforce this restriction?', '["Configure a Network Access Control List (NACL) on the S3 bucket.","Implement an S3 bucket policy with a `Condition` block specifying `aws:SourceIp`.","Use AWS WAF to filter requests to the S3 bucket based on IP address.","Create IAM user policies that explicitly deny access from non-corporate IP addresses."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and direct way to restrict access to an Amazon S3 bucket based on source IP address. An S3 bucket policy is a resource-based policy that can include a `Condition` element with the `aws:SourceIp` key to specify allowed IP ranges. This policy is evaluated for every request to the bucket. Option A (incorrect) is not applicable to Amazon S3 buckets; NACLs are used with Amazon VPC subnets. Option C (incorrect) is a web application firewall that protects resources like Amazon CloudFront distributions, Application Load Balancers, or API Gateway, but not direct access to S3 buckets. Option D (incorrect) would require managing individual IAM user policies for every user, which is less scalable and more complex than a single bucket policy, and it doesn''t prevent access from unauthorized IPs if a user''s credentials are compromised.', 29, 'm_29_3', 18, NULL, NULL),
  ('mock_28_all_1775006086746', 'An application running on an Amazon EC2 instance needs to retrieve a database password stored in AWS Secrets Manager. The development team must ensure that the EC2 instance can securely access this secret without hardcoding any credentials within the application or on the instance. Which is the most secure and recommended method for the EC2 instance to retrieve the secret?', '["Hardcode the secret directly into the application code running on the EC2 instance.","Store the secret in an encrypted file on the EC2 instance and decrypt it using a local key.","Attach an AWS IAM role to the EC2 instance with permissions to retrieve the secret from AWS Secrets Manager.","Store the secret as a SecureString in AWS Systems Manager Parameter Store and retrieve it from the EC2 instance."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS best practice for securely retrieving secrets from AWS Secrets Manager by an EC2 instance. By attaching an AWS IAM role with the necessary `secretsmanager:GetSecretValue` permissions to the EC2 instance, the instance can leverage its temporary credentials to access Secrets Manager. This eliminates the need to hardcode or manage any credentials on the instance, enhancing security. Option A (incorrect) is a severe anti-pattern (ap-2.1-002) as hardcoding secrets directly into application code is highly insecure. Option B (incorrect) introduces significant operational overhead and security risks by requiring manual key management and secure storage of the encrypted file on the instance. Option D (incorrect) is an anti-pattern (ap-2.2-001) for secrets that require rotation, as Secrets Manager is specifically designed for this, whereas Parameter Store SecureString does not support automatic rotation.', 29, 'm_29_3', 19, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is creating an AWS Lambda function that needs to store a non-sensitive configuration value, such as a service endpoint URL. This value should be encrypted at rest but does not require automatic rotation or advanced secret management features. The developer wants a simple, integrated solution. Which approach provides encryption at rest with minimal effort?', '["Store the value in AWS Secrets Manager and retrieve it at runtime.","Store the value as a SecureString in AWS Systems Manager Parameter Store.","Hardcode the value directly into the Lambda function''s source code.","Store the value as an environment variable in the AWS Lambda function configuration."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is a straightforward and effective way to store non-sensitive configuration values that require encryption at rest for a Lambda function. AWS Lambda automatically encrypts environment variables at rest using AWS KMS, providing a simple and integrated solution with minimal effort for values that do not require rotation. Option A (incorrect) is overkill and more expensive for a non-sensitive, non-rotating configuration value. AWS Secrets Manager is designed for highly sensitive secrets requiring rotation. Option B (incorrect) is a valid option for encrypted configuration, but for a simple non-sensitive, non-rotating value directly used by Lambda, environment variables are often simpler and more integrated. Option C (incorrect) is not encrypted at rest and is generally considered a poor practice for configuration values as it requires code changes for updates and can expose values in version control.', 29, 'm_29_3', 20, NULL, NULL);

