INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775006086746', 'A development team wants to establish a fully automated Continuous Integration and Continuous Delivery (CI/CD) pipeline for their containerized application. The pipeline needs to automatically retrieve source code, build Docker images, run tests, and deploy the application to Amazon ECS. Which sequence of AWS CodePipeline stages represents a standard and effective CI/CD workflow?', '["Build → Source → Deploy → Test","Source → Build → Test → Deploy","Test → Source → Build → Deploy","Deploy → Source → Build → Test"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) represents the standard and logical flow for a CI/CD pipeline using AWS CodePipeline. The ''Source'' stage retrieves the application code from a repository like AWS CodeCommit or GitHub. The ''Build'' stage then compiles the code, builds Docker images, and prepares artifacts, often using AWS CodeBuild. The ''Test'' stage runs automated tests (unit, integration, etc.) on the built artifacts, also typically using AWS CodeBuild. Finally, the ''Deploy'' stage deploys the tested application to the target environment, such as Amazon ECS, using services like AWS CodeDeploy. The other options present illogical or inefficient sequences for a CI/CD workflow.', 30, 'm_30_4', 5, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is setting up an AWS CodeBuild project to build a Java application. During the build process, the application needs to compile code, run unit tests, and package the application into a JAR file. Which file is used to define these build commands, environment variables, and artifact specifications for AWS CodeBuild?', '["Dockerfile","buildspec.yml","appspec.yml","template.yaml"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the `buildspec.yml` file, which is central to configuring an AWS CodeBuild project. This YAML file defines the build commands, environment variables, caching instructions, and artifact specifications for each phase of the build process (install, pre_build, build, post_build). Option A (incorrect) is a `Dockerfile`, used to define how a Docker image is built, not the CodeBuild project itself. Option C (incorrect) is an `appspec.yml` file, used by AWS CodeDeploy to manage deployment lifecycle hooks. Option D (incorrect) is a `template.yaml` file, typically used by AWS SAM to define serverless applications.', 30, 'm_30_4', 6, NULL, NULL),
  ('mock_28_all_1775006086746', 'A CI/CD pipeline built with AWS CodePipeline and AWS CodeBuild needs to access sensitive credentials, such as API keys for third-party services, during the build process. The security team mandates that these secrets must not be stored in plaintext or directly committed to the source code repository. Which is the MOST secure and recommended way to manage these environment variables in the CodeBuild project?', '["Store the secrets directly as plaintext environment variables in the CodeBuild project configuration.","Hardcode the secrets within the `buildspec.yml` file for easy access during the build.","Store the secrets in AWS Secrets Manager or AWS Systems Manager Parameter Store (SecureString) and reference them in the `buildspec.yml`.","Encrypt the secrets manually and store them in an Amazon S3 bucket, then decrypt them using a custom script in the `buildspec.yml`."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most secure and recommended approach. AWS Secrets Manager and AWS Systems Manager Parameter Store (SecureString) are designed for securely storing and managing sensitive information. CodeBuild can be configured to retrieve these secrets at runtime by referencing them in the `buildspec.yml` file, ensuring they are not exposed in plaintext in the build logs or source code, directly addressing anti-pattern [ap-3.4-001]. Option A (incorrect) directly violates the security mandate by storing secrets in plaintext environment variables, which are visible in the console and build logs, violating anti-pattern [ap-3.4-001]. Option B (incorrect) is highly insecure as it hardcodes sensitive information into the version-controlled `buildspec.yml`, making it easily accessible and difficult to rotate. Option D (incorrect) involves manual encryption and custom scripting, which adds operational overhead and is less secure than using dedicated secret management services like Secrets Manager or Parameter Store.', 30, 'm_30_4', 7, NULL, NULL),
  ('mock_28_all_1775006086746', 'A development team is building a CI/CD pipeline using AWS CodePipeline. After the build stage, the compiled application artifacts (e.g., JAR files, Docker images, CloudFormation templates) need to be stored securely and made accessible to subsequent stages, such as testing and deployment. Which AWS service is primarily used by CodePipeline for managing these build artifacts?', '["Amazon S3","AWS CodeCommit","AWS CodeArtifact","Amazon ECR"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon S3. AWS CodePipeline uses Amazon S3 buckets as its primary artifact store to pass outputs from one stage to inputs of another stage. For example, the build output from AWS CodeBuild is stored in an S3 bucket and then retrieved by AWS CodeDeploy for deployment. Option B (incorrect) is AWS CodeCommit, which is a source control service for storing Git repositories, not for build artifacts. Option C (incorrect) is AWS CodeArtifact, a fully managed artifact repository service for packages like Maven, npm, or PyPI, but CodePipeline''s internal artifact passing mechanism typically uses S3. Option D (incorrect) is Amazon ECR, a Docker container registry, used for storing Docker images but not general build artifacts like JARs or CloudFormation templates.', 30, 'm_30_4', 8, NULL, NULL),
  ('mock_28_all_1775006086746', 'A company wants to automate the deployment of their infrastructure changes defined in AWS CloudFormation templates. They need a robust CI/CD pipeline that can detect changes in a Git repository, validate the templates, and then deploy them to various AWS environments (dev, test, prod). Which AWS service combination is best suited to achieve this automated infrastructure deployment?', '["AWS CodeCommit for source control, AWS CodeBuild for template validation, and AWS CodePipeline for orchestration and CloudFormation deployments.","Manually upload CloudFormation templates to the AWS Management Console and execute stack updates.","Use AWS CloudFormation CLI to deploy templates directly from a local machine after manual validation.","Employ AWS Elastic Beanstalk to manage the deployment of CloudFormation templates to different environments."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a fully automated and integrated solution for deploying CloudFormation templates. AWS CodeCommit serves as the source control for the templates. AWS CodeBuild can be used in a build stage to validate the CloudFormation templates (e.g., using `cfn-lint`) before deployment. AWS CodePipeline orchestrates the entire workflow, including triggering on source changes, running the build/validation, and then executing CloudFormation stack updates or changesets in the deployment stage. Option B (incorrect) is a manual approach that is error-prone and lacks automation, version control, and consistency. Option C (incorrect) involves manual steps and local execution, which is not an automated CI/CD approach. Option D (incorrect) is incorrect because AWS Elastic Beanstalk is a platform for deploying web applications, not for managing and deploying arbitrary AWS CloudFormation templates directly.', 30, 'm_30_4', 9, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_30_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775006086746', 'A development team is building a new microservice that will run as a Docker container. They need to package this application efficiently for deployment to Amazon ECS, ensuring the final container image is as small as possible to reduce deployment times and resource consumption. Which best practice should they follow when preparing the Docker container artifact?', '["Include all development dependencies, test frameworks, and build tools in the final production Docker image.","Use a multi-stage Docker build to separate build-time dependencies from the final runtime image.","Store sensitive configuration data directly within the Docker image for easy access at runtime.","Build the Docker image on a developer''s local machine and manually upload it to Amazon ECR for each deployment."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the best practice for creating efficient and minimal Docker images. A multi-stage Docker build allows you to use a larger base image with build tools in an initial stage, then copy only the necessary compiled artifacts to a much smaller, production-ready base image in a subsequent stage. This significantly reduces the final image size, improving deployment times and reducing resource usage, directly addressing anti-pattern [ap-3.1-001]. Option A (incorrect) directly violates the goal of a small image size by including unnecessary development dependencies, test files, and build tools, which increases image size and pull times, violating anti-pattern [ap-3.1-001]. Option C (incorrect) is a security anti-pattern; sensitive configuration data should be injected at runtime using services like AWS Secrets Manager or AWS Systems Manager Parameter Store, not embedded in the image. Option D (incorrect) is a manual and inefficient process that lacks automation, version control, and repeatability, making it unsuitable for a professional deployment workflow.', 30, 'm_30_1', 10, NULL, NULL),
  ('mock_28_all_1775006086746', 'A software company is developing a new serverless application composed of several AWS Lambda functions and an Amazon DynamoDB table. They need to define, deploy, and manage these resources as a single unit using infrastructure as code. The solution should simplify the packaging and deployment of Lambda functions and their dependencies. Which AWS tool is specifically designed to meet these requirements for serverless applications?', '["AWS CloudFormation, writing raw JSON/YAML templates for each resource.","AWS Elastic Beanstalk, deploying the Lambda code as a web application.","AWS Serverless Application Model (SAM), using simplified syntax to define serverless resources.","AWS CodeDeploy, managing the deployment of individual Lambda function versions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Serverless Application Model (SAM). SAM is an open-source framework that extends AWS CloudFormation to provide a simplified way to define, package, and deploy serverless applications. It allows developers to use a concise YAML syntax to define Lambda functions, API Gateway APIs, DynamoDB tables, and other serverless resources, abstracting away much of the boilerplate CloudFormation. Option A (incorrect) is a valid tool for IaC, but SAM offers a higher-level abstraction specifically for serverless components, making it simpler for this use case. Option B (incorrect) is not suitable as AWS Elastic Beanstalk is for deploying web applications on EC2 or Docker containers, not directly for managing serverless Lambda functions. Option D (incorrect) is AWS CodeDeploy, which is a deployment service, but it doesn''t define the serverless application''s infrastructure as code; it manages the deployment of application revisions.', 30, 'm_30_1', 11, NULL, NULL),
  ('mock_28_all_1775006086746', 'A small startup needs to quickly deploy a Python web application to AWS without managing underlying servers or scaling infrastructure manually. The application requires an environment that can automatically handle load balancing, auto-scaling, and application health monitoring. Which AWS service provides a fully managed platform for deploying and running web applications with minimal operational overhead?', '["Amazon EC2 instances with manual configuration of load balancers and Auto Scaling groups.","AWS Lambda functions with Amazon API Gateway for handling HTTP requests.","AWS Elastic Beanstalk, which provisions and manages the underlying infrastructure.","Amazon ECS with Fargate, requiring manual setup of task definitions and service configurations."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Elastic Beanstalk. It is a fully managed service that makes it easy to deploy and scale web applications and services. Elastic Beanstalk handles the provisioning and management of underlying infrastructure (EC2 instances, load balancers, Auto Scaling groups, etc.), allowing developers to focus on their code. Option A (incorrect) requires significant manual configuration and management of EC2, load balancers, and Auto Scaling, which contradicts the ''minimal operational overhead'' requirement. Option B (incorrect) is a serverless option, but for a traditional Python web application, Elastic Beanstalk provides a more direct and managed environment without requiring a re-architecture to a serverless function model. Option D (incorrect) is Amazon ECS with Fargate, which is a great container service, but it still requires more configuration (task definitions, service setup) than Elastic Beanstalk for simply deploying a web application.', 30, 'm_30_1', 12, NULL, NULL),
  ('mock_28_all_1775006086746', 'A development team uses Git for version control and needs a secure, private repository hosted on AWS for their application code. The repository should integrate seamlessly with other AWS developer tools like AWS CodePipeline. Which AWS service provides a fully managed Git repository service for this purpose?', '["GitHub, requiring external integration and management.","AWS CodeCommit","Amazon S3, storing code archives as objects.","AWS CodeArtifact, for managing software packages."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS CodeCommit. It is a fully managed source control service that hosts secure Git-based repositories. CodeCommit integrates natively with other AWS developer tools like AWS CodePipeline, making it an ideal choice for teams wanting a private Git repository within the AWS ecosystem. Option A (incorrect) is GitHub, an external service that, while widely used, requires separate account management and external integration. Option C (incorrect) is Amazon S3, an object storage service, which is not designed for Git-based version control of source code. Option D (incorrect) is AWS CodeArtifact, which is a package repository service for managing application dependencies (like Maven, npm, PyPI packages), not for source code repositories.', 30, 'm_30_1', 13, NULL, NULL),
  ('mock_28_all_1775006086746', 'A developer is preparing an AWS Lambda function for deployment. The function''s deployment package currently includes large development libraries and test files that are not needed in production. This results in longer cold start times and increased storage costs. What is the MOST effective way to reduce the size of the Lambda deployment package?', '["Increase the Lambda function''s allocated memory to compensate for the larger package size.","Store the entire deployment package in an Amazon S3 bucket and refer to it from the Lambda function.","Exclude development dependencies and test files from the production deployment artifact.","Use AWS CodeArtifact to manage all dependencies, which automatically optimizes package size."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective way to reduce the size of the Lambda deployment package. By excluding development dependencies, test files, and other unnecessary artifacts from the production deployment, the package size is significantly reduced. This leads to faster upload times, quicker cold starts, and lower storage costs, directly addressing anti-pattern [ap-3.1-001]. Option A (incorrect) does not reduce package size; it merely attempts to mitigate the performance impact of a large package, which is not a root cause solution. Option B (incorrect) is a common way to deploy large Lambda packages, but it doesn''t reduce the package size itself; it only changes where it''s stored. Option D (incorrect) is incorrect because AWS CodeArtifact manages software packages and dependencies, but it does not automatically optimize the size of a Lambda deployment package; the developer must still manage what goes into the final artifact.', 30, 'm_30_1', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_30_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775006086746', 'A developer is building an AWS Lambda-based microservice and needs to rapidly iterate and debug the function code locally before deploying it to AWS. They want to simulate the Lambda runtime environment and invoke the function with test events without incurring AWS costs. Which AWS tool is specifically designed for local testing and debugging of Lambda functions?', '["AWS CodeBuild, to run tests in a cloud environment.","AWS CloudFormation, to deploy a test stack for each iteration.","AWS SDK for Python (Boto3), to invoke the remote Lambda function.","AWS SAM CLI, to invoke Lambda functions locally and simulate API Gateway events."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the AWS SAM CLI (Serverless Application Model Command Line Interface). The SAM CLI provides a local development and testing environment that allows developers to invoke Lambda functions locally, simulate API Gateway events, and debug their serverless applications without deploying them to AWS, thus avoiding costs and enabling rapid iteration. Option A (incorrect) is AWS CodeBuild, which is a cloud-based build service, not for local development and debugging. Option B (incorrect) is AWS CloudFormation, used for deploying infrastructure as code, which is too slow and costly for rapid local iteration. Option C (incorrect) is the AWS SDK, which is used to interact with AWS services programmatically, but it would invoke a deployed Lambda function on AWS, incurring costs and not providing a local debugging experience, violating anti-pattern [ap-3.2-001].', 30, 'm_30_2', 15, NULL, NULL),
  ('mock_28_all_1775006086746', 'A development team is building an application that uses Amazon DynamoDB as its primary data store. For local development and testing, they want to avoid incurring AWS costs and ensure that developers can work offline. Which solution allows them to run a local instance of DynamoDB for development purposes?', '["DynamoDB Local","Amazon RDS for local database emulation","AWS Systems Manager Parameter Store for storing mock data","Using a dedicated development AWS account for DynamoDB instances"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is DynamoDB Local. It is a downloadable version of Amazon DynamoDB that allows developers to write and test applications by running DynamoDB locally on their own computers, without incurring any AWS costs or requiring an internet connection. This is ideal for offline development and rapid iteration. Option B (incorrect) is Amazon RDS, a relational database service, which is not a local emulation for DynamoDB. Option C (incorrect) is AWS Systems Manager Parameter Store, used for storing configuration data, not for emulating a database. Option D (incorrect) involves using a dedicated AWS account, which incurs costs and requires an internet connection, directly contradicting the requirement to avoid AWS costs and work offline, violating anti-pattern [ap-3.2-001].', 30, 'm_30_2', 16, NULL, NULL),
  ('mock_28_all_1775006086746', 'A company is developing a new microservice that uses AWS Lambda. They need to test new features in an isolated environment before rolling them out to all users. The testing should involve shifting a small percentage of traffic to the new version, allowing for real-world validation without impacting the majority of users. Which AWS Lambda feature enables this type of controlled testing?', '["Lambda Layers, to isolate dependencies.","Lambda aliases with traffic shifting.","Lambda environment variables for feature flags.","Lambda reserved concurrency for performance testing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Lambda aliases with traffic shifting. AWS Lambda aliases allow you to point to different versions of a Lambda function. With traffic shifting, you can configure an alias to distribute incoming traffic between two Lambda function versions (e.g., 90% to the stable production version and 10% to the new test version). This enables canary deployments and controlled testing in an isolated environment with real user traffic, allowing for phased rollouts and easy rollbacks. Option A (incorrect) is Lambda Layers, used for managing common dependencies across multiple functions, not for traffic shifting or controlled testing of new features. Option C (incorrect) is Lambda environment variables, used for configuration, but not for managing traffic distribution or versions. Option D (incorrect) is Lambda reserved concurrency, used to control the maximum concurrent executions for a function, which is related to performance, not traffic shifting for testing new features.', 30, 'm_30_2', 17, NULL, NULL),
  ('mock_28_all_1775006086746', 'A development team is building a RESTful API using Amazon API Gateway. They require separate endpoints for development, staging, and production environments to facilitate testing and deployment. Each environment should have its own configuration, such as API keys and throttling limits. Which API Gateway feature allows for managing these distinct environments?', '["API Gateway resource policies, for access control.","API Gateway custom domain names, for branding.","API Gateway stages, for managing different deployment environments.","API Gateway usage plans, for controlling client access."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is API Gateway stages. An API Gateway stage is a logical reference to a specific state of an API. You can create multiple stages (e.g., `dev`, `staging`, `prod`), each with its own configuration, deployment, and monitoring settings. This allows developers to deploy and test different versions of their API in isolated environments. Option A (incorrect) is API Gateway resource policies, used for controlling access to the API. Option B (incorrect) is API Gateway custom domain names, used for branding and custom URLs, not for managing distinct deployment environments. Option D (incorrect) is API Gateway usage plans, used to control client access to API methods, often associated with API keys, but not for defining distinct deployment environments.', 30, 'm_30_2', 18, NULL, NULL),
  ('mock_28_all_1775006086746', 'A company is developing a critical application and needs to ensure that all new code changes are thoroughly tested for functionality and integration before deployment to production. They want to automate the execution of unit, integration, and end-to-end tests as part of their CI/CD pipeline. Which AWS service is best suited for running these automated tests in a managed and scalable environment?', '["AWS Lambda, by triggering individual test scripts as functions.","Amazon EC2 instances, manually provisioned and configured to run tests.","AWS CodeBuild, configured with a `buildspec.yml` to execute various test suites.","AWS CloudWatch Events, to schedule test runs at specific intervals."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS CodeBuild. AWS CodeBuild is a fully managed continuous integration service that compiles source code, runs tests, and produces software packages that are ready to deploy. It is highly scalable and integrates seamlessly with AWS CodePipeline. Developers can define all test commands and configurations within the `buildspec.yml` file, making it ideal for automating unit, integration, and end-to-end tests. Option A (incorrect) is AWS Lambda, which can run small, short-lived test scripts, but it''s not designed as a comprehensive, managed build and test environment for entire application test suites. Option B (incorrect) involves manually provisioning and managing EC2 instances, which adds significant operational overhead and is not a managed, scalable solution for automated testing. Option D (incorrect) is AWS CloudWatch Events, which can schedule events, but it doesn''t provide the execution environment for running tests; it would need to trigger another service like Lambda or CodeBuild.', 30, 'm_30_2', 19, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 19
WHERE id = 'mock_28_all_1775006086746';

