INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A new mobile application needs to allow users to sign up, sign in, and then access AWS services like Amazon S3 to upload profile pictures directly from their device. The development team wants to minimize custom code for user management and securely grant temporary, limited access to AWS resources. Which approach offers the LEAST custom code for user authentication and secure AWS service access?', '["Implement Amazon Cognito User Pools for user authentication and Amazon Cognito Identity Pools to vend temporary AWS credentials for S3 access.","Use AWS IAM users and groups for each mobile application user, providing them with individual access keys to interact with Amazon S3.","Develop a custom authentication service on Amazon EC2 that issues JWT tokens, then use AWS STS AssumeRole to vend temporary credentials.","Integrate with a third-party authentication provider and hardcode their API keys into the mobile application to access Amazon S3 directly."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages Amazon Cognito User Pools for managing user sign-up and sign-in, and Amazon Cognito Identity Pools to exchange the User Pool tokens for temporary, limited-privilege AWS credentials. This approach minimizes custom code for user management and securely grants access to AWS services like Amazon S3, aligning with the principle of least privilege. Option B (incorrect) is highly impractical and insecure for mobile applications, as managing individual IAM users for potentially thousands or millions of app users is not scalable and exposes long-lived credentials. Option C (incorrect) involves significant custom development and operational overhead for building and maintaining a custom authentication service, which goes against the ''LEAST custom code'' constraint. Option D (incorrect) is a severe security anti-pattern, as hardcoding API keys in a mobile application can lead to their compromise and unauthorized access to resources.', 29, 'm_29_1', 1, NULL, NULL),
  ('mock_28_all_1775007111773', 'A serverless API, built with Amazon API Gateway and AWS Lambda, processes sensitive customer data. The API needs to be secured so that only authenticated users from a corporate directory can access it. The solution must integrate with an existing SAML 2.0 identity provider. Which API Gateway authorization method provides this functionality with MINIMAL operational overhead?', '["Configure an AWS Lambda authorizer that validates JWT tokens issued by the SAML 2.0 identity provider.","Integrate Amazon Cognito User Pools with the SAML 2.0 identity provider and configure an Amazon Cognito User Pool authorizer for API Gateway.","Use IAM authorization for API Gateway, requiring users to assume an IAM role with appropriate permissions before calling the API.","Implement a custom authorizer on an Amazon EC2 instance that performs SAML 2.0 assertion validation for each API request."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution. Amazon Cognito User Pools can be configured to federate with SAML 2.0 identity providers. Once integrated, an Amazon Cognito User Pool authorizer can be directly attached to Amazon API Gateway methods, offloading authentication and token validation with minimal operational overhead. Option A (incorrect) would require writing and maintaining custom AWS Lambda code to parse and validate SAML assertions or JWT tokens, increasing development and operational burden. Option C (incorrect) would require users to have IAM credentials or assume roles, which is not ideal for direct user authentication from a corporate directory via SAML. Option D (incorrect) introduces significant operational overhead by requiring the management of an EC2 instance for a custom authorizer, which is less scalable and more complex than a managed service like Amazon Cognito.', 29, 'm_29_1', 2, NULL, NULL),
  ('mock_28_all_1775007111773', 'An AWS Lambda function needs to read and write objects to a specific Amazon S3 bucket in the same AWS account. The security team mandates that the function should only have the absolute minimum necessary permissions and that no long-lived credentials should be stored in the function code or environment variables. How should the Lambda function be granted access to Amazon S3?', '["Generate an IAM user with S3 access keys, then store these keys as encrypted environment variables in the AWS Lambda function.","Create an IAM user with S3 access, and use the AWS SDK''s default credential provider chain to retrieve credentials from the EC2 instance profile.","Attach an IAM role to the AWS Lambda function, granting it specific permissions to the designated Amazon S3 bucket.","Embed the S3 bucket''s access policy directly into the AWS Lambda function code, allowing it to assume temporary permissions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS best practice for granting permissions to AWS services like AWS Lambda. By attaching an IAM role to the Lambda function, it automatically receives temporary credentials from AWS STS, eliminating the need to store any long-lived credentials in the function code or environment variables. The IAM role can be configured with a granular policy to grant only the necessary permissions to the specific Amazon S3 bucket, adhering to the principle of least privilege. Option A (incorrect) is an anti-pattern as it involves storing long-lived credentials, even if encrypted, which increases the risk of exposure and management complexity. Option B (incorrect) refers to EC2 instance profiles, which are not applicable to AWS Lambda functions. Option D (incorrect) is not a valid or secure method for granting permissions; IAM policies are defined and managed separately from application code.', 29, 'm_29_1', 3, NULL, NULL),
  ('mock_28_all_1775007111773', 'A web application hosted on Amazon EC2 instances needs to securely call AWS APIs, such as Amazon DynamoDB, without embedding access keys directly into the application''s configuration files. The solution should dynamically provide temporary credentials to the application. Which is the MOST secure and operationally efficient method?', '["Store IAM user access keys in AWS Secrets Manager and retrieve them programmatically from the EC2 instances.","Create an IAM user with programmatic access, then store the access key and secret key in an encrypted file on the EC2 instance.","Use AWS Systems Manager Parameter Store SecureString to store IAM user access keys, then retrieve them at application startup.","Attach an IAM role to the Amazon EC2 instance profile, granting it the necessary permissions to interact with Amazon DynamoDB."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most secure and operationally efficient method. By attaching an IAM role to the Amazon EC2 instance profile, the application running on the EC2 instance can automatically receive temporary, frequently rotated credentials from the AWS metadata service. This eliminates the need to store any long-lived credentials on the instance or in application code, aligning with AWS security best practices. Option A (incorrect) involves storing long-lived IAM user access keys in AWS Secrets Manager, which is better than hardcoding but still requires managing IAM users and their keys, and doesn''t fully leverage the temporary credential vending of instance profiles. Option B (incorrect) is a security anti-pattern as it involves storing long-lived credentials directly on the instance, increasing the risk of compromise. Option C (incorrect) also involves storing long-lived IAM user access keys, and while Parameter Store provides encryption, it''s not designed for automatic rotation of these specific credentials and doesn''t offer the same level of security as instance profiles for EC2.', 29, 'm_29_1', 4, NULL, NULL),
  ('mock_28_all_1775007111773', 'A third-party mobile application needs to authenticate users using social identity providers (e.g., Google, Facebook) and then grant them temporary, federated access to upload files to a dedicated Amazon S3 bucket in your AWS account. The solution should manage the identity federation and credential vending. Which combination of services best meets this requirement with MINIMAL development effort?', '["Use Amazon Cognito User Pools to handle social identity provider authentication and Amazon Cognito Identity Pools to exchange tokens for temporary AWS credentials.","Implement a custom authentication backend on Amazon EC2 to integrate with social identity providers and use AWS STS AssumeRole to issue temporary credentials.","Configure Amazon Cognito User Pools for social login and directly use the JWT tokens issued by User Pools to sign requests to Amazon S3.","Create IAM users for each social identity provider and configure IAM policies to grant direct access to the Amazon S3 bucket."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the recommended approach. Amazon Cognito User Pools simplify user authentication, including federation with social identity providers like Google and Facebook. Amazon Cognito Identity Pools then take the authentication tokens (from User Pools or directly from social providers) and exchange them for temporary, limited-privilege AWS credentials, which the mobile application can use to securely access Amazon S3. This combination minimizes development effort for both authentication and authorization. Option B (incorrect) involves significant custom development and operational overhead to build and maintain an authentication backend, which goes against the ''MINIMAL development effort'' constraint. Option C (incorrect) is incorrect because JWT tokens from User Pools are for application-level authentication; they cannot directly authorize calls to AWS services like Amazon S3 without being exchanged for AWS credentials via an Identity Pool or STS. This option confuses the purpose of User Pools and Identity Pools (Anti-pattern ap-2.1-001). Option D (incorrect) is highly impractical and insecure; creating individual IAM users for potentially millions of social users is not scalable and violates security best practices.', 29, 'm_29_1', 5, NULL, NULL),
  ('mock_28_all_1775007111773', 'An internal web application uses Amazon API Gateway to expose a set of microservices implemented with AWS Lambda. Access to these APIs must be restricted to users who have successfully authenticated through a custom authentication service. The custom service issues JWT tokens. Which API Gateway authorization method should be used?', '["IAM authorization, requiring users to sign requests with AWS credentials obtained from an IAM role.","An AWS Lambda authorizer that validates the JWT tokens issued by the custom authentication service.","An Amazon Cognito User Pool authorizer, configured to validate tokens from the custom authentication service.","AWS WAF to filter requests based on custom HTTP headers containing authentication information."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate choice. An AWS Lambda authorizer (formerly known as a custom authorizer) allows you to implement custom logic to authorize API requests. In this scenario, the Lambda authorizer would receive the JWT token from the incoming request, validate it against the custom authentication service''s public key or introspection endpoint, and return an IAM policy that grants or denies access to the API Gateway resources. Option A (incorrect) is not suitable for end-user authentication with a custom service; IAM authorization is typically used for AWS principals or federated users assuming IAM roles. Option C (incorrect) is designed to work with Amazon Cognito User Pools; it cannot directly validate JWT tokens from an arbitrary custom authentication service unless that service is integrated as an identity provider with a User Pool. Option D (incorrect) is a web application firewall primarily used for filtering malicious traffic, not for implementing custom authentication and authorization logic based on JWT tokens.', 29, 'm_29_1', 6, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer is building an application that interacts with multiple AWS services. To simplify local development and testing, they want to use temporary AWS credentials that are automatically refreshed, instead of configuring static IAM user access keys. Which AWS service should the developer use to obtain these temporary credentials?', '["AWS Secrets Manager to store and retrieve long-lived IAM user access keys.","AWS Systems Manager Parameter Store to store IAM user access keys as SecureStrings.","AWS Security Token Service (STS) to assume an IAM role and obtain temporary security credentials.","Amazon Cognito Identity Pools to get temporary credentials for unauthenticated users."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the primary service for obtaining temporary, short-lived AWS security credentials. Developers can use AWS STS to assume an IAM role (e.g., one configured for development) and receive temporary credentials that are automatically refreshed by the AWS SDK, simplifying local development and testing without the need for static, long-lived access keys. Option A (incorrect) is for storing and managing secrets, including long-lived credentials, but it doesn''t inherently provide temporary, automatically refreshed credentials in the same way STS does for assuming roles. Option B (incorrect) is for storing configuration data and secrets, but it''s not designed for vending temporary, automatically refreshed AWS credentials; it would typically store static credentials (Anti-pattern ap-2.1-002). Option D (incorrect) is used for vending temporary credentials primarily for mobile and web applications, often after user authentication, not typically for a developer''s local environment to interact with multiple AWS services directly.', 29, 'm_29_1', 7, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_29_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A company stores sensitive customer documents in an Amazon S3 bucket. Compliance requirements dictate that all data must be encrypted at rest using keys that the company controls and can audit. The solution should also allow for key rotation. Which Amazon S3 encryption option, combined with a key management service, meets these requirements?', '["Server-Side Encryption with Amazon S3-managed Keys (SSE-S3).","Server-Side Encryption with Customer-Provided Keys (SSE-C).","Client-Side Encryption with a client-managed encryption library.","Server-Side Encryption with AWS KMS-managed Keys (SSE-KMS) using a customer managed key (CMK)."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most suitable choice. SSE-KMS allows Amazon S3 to encrypt objects using AWS KMS. By selecting a customer managed key (CMK) within AWS KMS, the company gains full control over the encryption key, including the ability to define key policies, audit key usage through AWS CloudTrail, and configure automatic key rotation. Option A (incorrect) uses keys managed entirely by Amazon S3, which does not provide the customer with control or audit capabilities over the encryption keys. Option B (incorrect) requires the customer to provide and manage their own encryption keys, which increases operational overhead and complexity, and does not leverage AWS KMS for key management or rotation. Option C (incorrect) also requires the customer to manage the encryption process and keys entirely on their side, increasing complexity and potentially missing out on AWS-managed key rotation and auditing features.', 29, 'm_29_2', 8, NULL, NULL),
  ('mock_28_all_1775007111773', 'A web application transmits sensitive user data over the internet to an API Gateway endpoint. The security team requires that all data in transit must be encrypted to prevent eavesdropping and tampering. Which mechanism ensures this encryption for API Gateway?', '["Enforce HTTPS for all API Gateway endpoints.","Configure AWS WAF to block unencrypted HTTP requests.","Use AWS KMS to encrypt the API Gateway endpoint configuration.","Implement client-side encryption of data before sending it to API Gateway."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the standard and most effective way to ensure data in transit is encrypted for web applications. Amazon API Gateway automatically supports HTTPS (TLS) endpoints. By enforcing HTTPS, all communication between the client and API Gateway is encrypted, protecting data from eavesdropping and tampering. Option B (incorrect) is a web application firewall that primarily filters malicious traffic; while it can block HTTP, it doesn''t inherently provide the encryption itself. Option C (incorrect) is used for encrypting data at rest and managing encryption keys, not for encrypting data in transit over a network connection to an API endpoint. Option D (incorrect) adds complexity to the client application and is typically used for end-to-end encryption of specific data fields, not for securing the entire communication channel, which is best handled by TLS/HTTPS.', 29, 'm_29_2', 9, NULL, NULL),
  ('mock_28_all_1775007111773', 'An application stores database credentials that need to be rotated automatically every 90 days. The credentials are used by an AWS Lambda function to connect to an Amazon RDS database. The solution should provide secure storage and automatic rotation. Which AWS service should be used?', '["AWS Systems Manager Parameter Store (SecureString) to store the credentials.","AWS Secrets Manager to store and automatically rotate the credentials.","AWS KMS to encrypt the credentials and store them in an Amazon S3 bucket.","Store the credentials as encrypted environment variables in the AWS Lambda function."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for this use case. AWS Secrets Manager provides secure storage for credentials, API keys, and other secrets, and it natively supports automatic rotation for various database types, including Amazon RDS. This meets the requirement for secure storage and automatic rotation. Option A (incorrect) AWS Systems Manager Parameter Store (SecureString) can store encrypted secrets, but it does not support automatic rotation of secrets (Anti-pattern ap-2.2-001), making it unsuitable for credentials requiring regular rotation. Option C (incorrect) would require significant custom development to implement the storage, retrieval, and rotation logic, increasing operational overhead and complexity. Option D (incorrect) is a security anti-pattern; while Lambda environment variables can be encrypted at rest, they are not designed for automatic rotation and could still be exposed if not managed carefully.', 29, 'm_29_2', 10, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer needs to encrypt specific data fields within an application before storing them in a database. The encryption keys should be managed centrally by AWS, and the application should only have permission to encrypt and decrypt data, not manage the keys themselves. Which AWS service should the developer integrate with their application for this purpose?', '["AWS Systems Manager Parameter Store (SecureString) for encryption.","AWS Secrets Manager for key management and encryption.","AWS Key Management Service (KMS) for cryptographic operations using data keys.","Amazon S3 server-side encryption for application-level data."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate service. AWS KMS allows the application to request data keys (using GenerateDataKey) for encrypting specific data fields. The application then uses these data keys to perform client-side encryption and decryption. AWS KMS centrally manages the master keys (CMKs) that protect these data keys, ensuring the application only performs cryptographic operations and does not have direct access to or control over the master keys, fulfilling the requirement for centralized key management and least privilege. Option A (incorrect) is for storing configuration and secrets, not for performing general-purpose cryptographic operations within an application. Option B (incorrect) is primarily for storing, managing, and rotating secrets, not for general-purpose data encryption within an application. Option D (incorrect) is for encrypting objects stored in Amazon S3, not for application-level encryption of data fields before storage in a database.', 29, 'm_29_2', 11, NULL, NULL),
  ('mock_28_all_1775007111773', 'An application processes files uploaded to an Amazon S3 bucket. The files contain sensitive information and must be encrypted at rest. The development team prefers a solution where encryption is handled by Amazon S3 itself, using keys managed by AWS, to minimize application-side complexity. Which Amazon S3 encryption option should be chosen?', '["Server-Side Encryption with AWS KMS-managed Keys (SSE-KMS) using a customer managed key (CMK).","Server-Side Encryption with Customer-Provided Keys (SSE-C).","Client-Side Encryption using the Amazon S3 Encryption Client.","Server-Side Encryption with Amazon S3-managed Keys (SSE-S3)."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the simplest option for this scenario. SSE-S3 uses Amazon S3-managed encryption keys to encrypt objects at rest. This option requires no additional configuration or key management from the customer, as Amazon S3 handles everything, thus minimizing application-side complexity. Option A (incorrect) uses AWS KMS, but specifically a customer managed key (CMK), which gives the customer more control and auditability but also introduces more management overhead than SSE-S3. Option B (incorrect) requires the customer to provide and manage their own encryption keys, increasing complexity. Option C (incorrect) involves implementing encryption logic within the application itself, which goes against the goal of minimizing application-side complexity.', 29, 'm_29_2', 12, NULL, NULL),
  ('mock_28_all_1775007111773', 'An AWS Lambda function requires access to a non-rotating API key for a third-party service. This API key is a static secret and does not need automatic rotation. The development team wants to store this secret securely and retrieve it programmatically. Which AWS service is the MOST cost-effective and appropriate for this requirement?', '["AWS Systems Manager Parameter Store (SecureString).","AWS Secrets Manager.","Store the API key in an encrypted Amazon S3 bucket.","Encrypt the API key with AWS KMS and store it as an environment variable in the Lambda function."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and appropriate solution for storing static, non-rotating secrets. AWS Systems Manager Parameter Store (SecureString) provides secure, encrypted storage for configuration data and secrets, and it is generally more cost-effective for static secrets compared to AWS Secrets Manager, especially when automatic rotation is not required. Option B (incorrect) AWS Secrets Manager is designed for secrets that require automatic rotation and offers advanced features, making it more expensive than Parameter Store for static secrets (Anti-pattern ap-2.2-001). Option C (incorrect) would require custom implementation for secure retrieval and access control, increasing operational overhead. Option D (incorrect) stores the secret directly in the Lambda function''s configuration, which, while encrypted at rest by Lambda, is generally less flexible for centralized management and retrieval compared to Parameter Store.', 29, 'm_29_2', 13, NULL, NULL),
  ('mock_28_all_1775007111773', 'A company needs to ensure that all data stored in Amazon S3 is encrypted at rest using a unique encryption key for each object, and that these keys are further encrypted by a master key. This ''envelope encryption'' pattern is required for compliance. Which combination of services should be used?', '["Amazon S3 with Server-Side Encryption with Customer-Provided Keys (SSE-C).","Amazon S3 with Server-Side Encryption with AWS KMS-managed Keys (SSE-KMS).","Amazon S3 with Server-Side Encryption with Amazon S3-managed Keys (SSE-S3).","Client-Side Encryption with a custom encryption library and AWS KMS."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly implements the envelope encryption pattern. When using SSE-KMS, Amazon S3 encrypts each object with a unique data key. This data key is then encrypted by a customer master key (CMK) in AWS KMS. The encrypted data key is stored alongside the encrypted data. When an object is retrieved, the encrypted data key is sent to KMS for decryption, and then the data key is used to decrypt the object. This provides the desired envelope encryption with a managed service. Option A (incorrect) requires the customer to manage and provide the encryption keys, which does not leverage AWS KMS for the master key or the envelope encryption pattern. Option C (incorrect) uses keys managed entirely by Amazon S3 and does not expose the envelope encryption mechanism to the customer or allow for customer control over the master key. Option D (incorrect) would require significant custom development to implement the client-side encryption and key management, increasing complexity and operational overhead.', 29, 'm_29_2', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_29_3
