INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'An AWS Lambda function processes user requests that may contain Personally Identifiable Information (PII). The security team mandates that PII must never be exposed in application logs, even for debugging purposes. Which action should the developer take to comply with this requirement?', '["Configure Amazon CloudWatch Logs to automatically redact PII from log streams using log groups.","Implement a custom AWS Lambda authorizer to filter out PII from incoming requests before processing.","Modify the AWS Lambda function code to sanitize or redact sensitive PII fields before logging any data to Amazon CloudWatch Logs.","Store all logs in an encrypted Amazon S3 bucket instead of Amazon CloudWatch Logs to prevent PII exposure."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the direct and most effective way to prevent sensitive PII from appearing in logs. The application code itself is responsible for identifying and redacting or sanitizing sensitive data before it is written to any log destination, including Amazon CloudWatch Logs. This ensures that PII never leaves the application in an unmasked form within logs (Anti-pattern ap-2.3-001). Option A (incorrect) Amazon CloudWatch Logs does not have a built-in feature to automatically redact PII from arbitrary log streams; this functionality would need to be implemented upstream. Option B (incorrect) an AWS Lambda authorizer is for authorization, not for modifying or sanitizing request payloads for logging purposes. Option D (incorrect) storing logs in an encrypted S3 bucket encrypts the data at rest, but it does not prevent the PII from being present in the logs in the first place, which is the core requirement.', 29, 'm_29_3', 15, NULL, NULL),
  ('mock_28_all_1775007111773', 'An application deployed on AWS Lambda needs to access a database password. The security policy dictates that credentials should not be hardcoded or stored directly in environment variables. The password needs to be retrieved securely at runtime. Which AWS service should be used to store and retrieve the password?', '["Store the password as a SecureString in AWS Systems Manager Parameter Store.","Hardcode the password in the AWS Lambda function code and encrypt the deployment package.","Store the password in an encrypted Amazon S3 bucket and retrieve it via the AWS SDK.","AWS Secrets Manager to store the password, retrieved by the AWS Lambda function at runtime."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the recommended and most secure approach for managing database passwords for AWS Lambda functions. AWS Secrets Manager is specifically designed for storing, managing, and retrieving secrets like database credentials. Lambda functions can be granted IAM permissions to retrieve secrets from Secrets Manager at runtime, ensuring that credentials are not hardcoded or stored in environment variables. Option A (incorrect) AWS Systems Manager Parameter Store (SecureString) can store secrets, but it''s generally less suitable for database passwords that often require automatic rotation, a feature natively supported by Secrets Manager. Option B (incorrect) is a severe security anti-pattern; hardcoding credentials, even in an encrypted package, is insecure and violates best practices. Option C (incorrect) would require custom implementation for secure storage, access control, and retrieval logic, adding unnecessary complexity compared to a managed service like Secrets Manager.', 29, 'm_29_3', 16, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer needs to store configuration parameters for an AWS Lambda function, including some non-sensitive API endpoints and a sensitive database connection string. The sensitive string must be encrypted at rest. Which is the MOST appropriate and cost-effective solution for storing these parameters?', '["Store non-sensitive parameters as plain text and the sensitive connection string as a SecureString in AWS Systems Manager Parameter Store.","Store all parameters, both sensitive and non-sensitive, in AWS Secrets Manager.","Store all parameters as environment variables in the AWS Lambda function, encrypting the sensitive ones with AWS KMS.","Store non-sensitive parameters in an Amazon S3 bucket and the sensitive connection string in AWS Secrets Manager."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate and cost-effective solution. AWS Systems Manager Parameter Store allows storing both plain text and encrypted (SecureString) parameters. This meets the requirement for encrypting the sensitive connection string at rest while providing a centralized, managed service for all configuration parameters. It''s generally more cost-effective for static or infrequently changing secrets compared to AWS Secrets Manager. Option B (incorrect) AWS Secrets Manager is overkill and more expensive for non-sensitive configuration parameters and for sensitive ones that do not require automatic rotation. Option C (incorrect) while Lambda environment variables can be encrypted at rest, Parameter Store offers a more centralized and manageable solution for configuration parameters, especially when shared across multiple functions or services. Option D (incorrect) storing non-sensitive parameters in Amazon S3 would require custom logic for retrieval and management, increasing complexity compared to Parameter Store.', 29, 'm_29_3', 17, NULL, NULL),
  ('mock_28_all_1775007111773', 'An AWS Lambda function processes data and then stores it in an Amazon S3 bucket. The function''s IAM role currently has broad write access to all S3 buckets. The security team wants to restrict the function''s write access to only a specific prefix within a single S3 bucket. How can this be achieved with LEAST operational overhead?', '["Implement a custom AWS Lambda authorizer to validate S3 write requests based on the object prefix.","Modify the IAM policy attached to the Lambda function''s execution role to include resource-level permissions with a condition for the specific S3 bucket and prefix.","Configure an Amazon S3 bucket policy on the target bucket to deny write access to all but the specific prefix for the Lambda function''s role.","Use AWS WAF to filter out S3 write requests that do not target the allowed prefix for the Lambda function."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most direct and efficient way to implement least privilege for an AWS Lambda function''s S3 access. By modifying the IAM policy attached to the Lambda function''s execution role, you can specify the exact S3 bucket and prefix the function is allowed to write to, using resource-level permissions and IAM policy conditions. This is a standard and highly effective IAM feature with minimal operational overhead. Option A (incorrect) would involve significant custom development and operational overhead for an AWS Lambda authorizer, which is typically used for API Gateway authorization, not for controlling internal AWS service access. Option C (incorrect) while S3 bucket policies can be used, modifying the IAM role directly is generally preferred for restricting permissions of an AWS principal (like a Lambda function) and often simpler to manage when the principal''s permissions need to be restricted across various services. Option D (incorrect) AWS WAF is a web application firewall and is not used for controlling internal AWS service-to-service permissions like Lambda to S3.', 29, 'm_29_3', 18, NULL, NULL),
  ('mock_28_all_1775007111773', 'An AWS Lambda function uses an environment variable to store a database connection string. The security team is concerned that this sensitive information could be exposed if the Lambda function''s configuration is inspected. They require the environment variable to be encrypted at rest. How can this be achieved?', '["Store the connection string in AWS Secrets Manager and retrieve it at runtime, instead of using an environment variable.","Encrypt the connection string with AWS KMS client-side and store the ciphertext as the environment variable.","AWS Lambda automatically encrypts environment variables at rest using an AWS KMS key.","Store the connection string as a SecureString in AWS Systems Manager Parameter Store and reference it in the Lambda environment variable."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the correct statement regarding AWS Lambda environment variables. AWS Lambda automatically encrypts all environment variables at rest using an AWS KMS key. By default, it uses an AWS-managed key, but you can configure it to use a customer managed key (CMK) for additional control. This ensures that the sensitive connection string is encrypted when stored. Option A (incorrect) is a best practice for managing secrets that require rotation or more advanced management, but it doesn''t directly address the requirement of encrypting an *existing* environment variable. Option B (incorrect) would require the developer to manually implement client-side encryption and decryption logic within the Lambda function, which is unnecessary given Lambda''s built-in encryption. Option D (incorrect) while Parameter Store SecureString stores secrets encrypted, referencing it in a Lambda environment variable would still mean the value is passed to the environment, and Lambda''s built-in encryption is already handling that layer.', 29, 'm_29_3', 19, NULL, NULL),
  ('mock_28_all_1775007111773', 'A new feature in an application requires a new API key for a third-party service. This API key is critical for the application''s functionality and must be securely stored and retrieved by an Amazon EC2 instance at runtime, without being embedded in the application''s code or configuration files. Which AWS service is best suited for this requirement?', '["Store the API key as an encrypted file on the Amazon EC2 instance''s EBS volume.","Store the API key as a SecureString in AWS Systems Manager Parameter Store and retrieve it at application startup.","Embed the API key directly into the application''s environment variables on the Amazon EC2 instance.","AWS Secrets Manager to store the API key, retrieved by the Amazon EC2 instance at runtime."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the best choice for securely storing and retrieving API keys for applications running on Amazon EC2 instances. AWS Secrets Manager provides a centralized, managed service for secrets. The EC2 instance can be granted an IAM role with permissions to retrieve the secret from Secrets Manager at runtime, ensuring the key is never hardcoded or stored directly on the instance. Option A (incorrect) storing the API key as an encrypted file on the EBS volume is better than plain text but still requires manual key management and retrieval logic, increasing operational overhead and risk compared to a managed service. Option B (incorrect) AWS Systems Manager Parameter Store (SecureString) can store secrets, but Secrets Manager offers more advanced features like automatic rotation and integration with other services, which are often beneficial for critical API keys. Option C (incorrect) embedding the API key directly into environment variables is a security risk as it can be easily inspected or exposed.', 29, 'm_29_3', 20, NULL, NULL),
  ('mock_28_all_1775007111773', 'An AWS Lambda function is designed to process incoming events, and its logs are sent to Amazon CloudWatch Logs. During development, detailed logging was enabled, which sometimes includes entire request payloads. The security team has identified that these payloads can contain sensitive customer data. Which action should the developer take to prevent sensitive data from being logged, while still providing sufficient debugging information?', '["Implement structured logging within the AWS Lambda function to redact or exclude sensitive fields from log entries before sending them to Amazon CloudWatch Logs.","Configure Amazon CloudWatch Logs to automatically filter and redact sensitive data based on predefined patterns.","Disable all logging for the AWS Lambda function to prevent any sensitive data from being captured.","Store all raw request payloads in an encrypted Amazon S3 bucket instead of logging them to CloudWatch Logs."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and compliant approach. By implementing structured logging within the AWS Lambda function, the developer can explicitly control what data is logged. This allows for redacting sensitive fields, excluding entire sensitive payloads, or logging only non-sensitive metadata, ensuring that PII or other sensitive customer data never reaches Amazon CloudWatch Logs (Anti-pattern ap-2.3-001). This also allows for sufficient debugging information to be retained. Option B (incorrect) Amazon CloudWatch Logs does not natively provide automatic, intelligent filtering and redaction of sensitive data based on content; this logic must be implemented upstream. Option C (incorrect) disabling all logging would severely hinder debugging and operational monitoring, which is not a practical solution. Option D (incorrect) storing raw request payloads in Amazon S3, even if encrypted, still means the sensitive data is stored and potentially accessible, which might violate compliance requirements if the goal is to prevent it from being stored at all in logs.', 29, 'm_29_3', 21, NULL, NULL);

