INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A development team is building a serverless application using AWS Lambda and Amazon DynamoDB. They need to rapidly test new Lambda function code locally before deploying to a development AWS account, ensuring minimal cost and quick feedback loops. Which approach best meets these requirements?', '["Use AWS SAM CLI to invoke Lambda functions locally and DynamoDB Local for the database.","Deploy the Lambda function to a dedicated development AWS account and test against a development DynamoDB table.","Manually upload the Lambda code to a test Lambda function in the production account and use a mock DynamoDB endpoint.","Utilize AWS CodeBuild to run all Lambda tests in the cloud against a temporary DynamoDB instance for each code change."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective approach for local testing with minimal cost and fast feedback. AWS SAM CLI allows local invocation of Lambda functions, and DynamoDB Local provides a local, in-memory version of DynamoDB, eliminating AWS costs and network latency during development. Option B (incorrect) involves deploying to an AWS account, which incurs costs and is slower than local testing, violating the ''minimal cost and quick feedback'' constraint. Option C (incorrect) involves using the production account, which is an anti-pattern for testing (ap-3.2-001) due to risk of data corruption and cost, and manual upload is inefficient. Option D (incorrect) uses AWS CodeBuild, which is suitable for automated CI/CD testing but not for rapid local development and debugging, and it still incurs cloud costs.', 30, 'm_30_3', 1, NULL, NULL),
  ('mock_28_all_1775007111773', 'A development team is building a new microservice that processes data using AWS Lambda. They want to automate unit and integration tests as part of their CI/CD pipeline, ensuring code quality before deployment to a staging environment. Which AWS service should be integrated into the pipeline for automated test execution?', '["AWS CodeDeploy to manage test execution on EC2 instances.","AWS CodeBuild to compile code, run unit tests, and execute integration tests.","AWS CodeCommit to store test scripts alongside the application code.","Amazon S3 to store test results and logs for manual review."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the primary service for automated test execution within an AWS CI/CD pipeline. AWS CodeBuild is a fully managed build service that can compile source code, run unit tests, and execute integration tests as part of a buildspec.yml configuration. Option A (incorrect) is used for deploying applications, not for executing tests. Option C (incorrect) is a version control service for storing code, not for executing tests. Option D (incorrect) is object storage and can store test artifacts, but it does not execute the tests itself.', 30, 'm_30_3', 2, NULL, NULL),
  ('mock_28_all_1775007111773', 'A company is developing a new serverless API using AWS Lambda and Amazon API Gateway. Developers need to simulate API Gateway events and Lambda function invocations on their local machines to debug and validate business logic without incurring AWS charges. Which tool is MOST suitable for this purpose?', '["AWS CloudFormation to deploy a temporary test stack in a dev account.","AWS SAM CLI to emulate API Gateway and Lambda locally.","AWS CodePipeline to run a local build and test stage.","AWS Elastic Beanstalk to host a local API mock server."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for local development and testing of serverless applications. AWS SAM CLI allows developers to locally invoke Lambda functions, simulate API Gateway events, and even run entire serverless applications on their machines, significantly speeding up the development and debugging cycle without incurring AWS costs. Option A (incorrect) is for deploying infrastructure as code to AWS, not for local testing. Option C (incorrect) is a CI/CD service for automating workflows in the cloud, not for local emulation. Option D (incorrect) is a platform-as-a-service for web applications, not for local serverless emulation.', 30, 'm_30_3', 3, NULL, NULL),
  ('mock_28_all_1775007111773', 'A team is developing a data processing application using AWS Lambda that interacts with an Amazon DynamoDB table. They need a way to run integration tests against a local version of DynamoDB to avoid costs and dependencies on cloud resources during development. Which solution should they implement?', '["Use a dedicated Amazon DynamoDB table in a separate development AWS account.","Integrate DynamoDB Local into their development environment.","Mock DynamoDB API calls using a custom in-memory database.","Set up a local PostgreSQL database and migrate data from DynamoDB for testing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the recommended solution for local DynamoDB development. DynamoDB Local provides a downloadable version of DynamoDB that runs on a developer''s machine, allowing them to test their application''s interactions with DynamoDB without incurring AWS costs or requiring an internet connection. Option A (incorrect) would incur AWS costs and still depend on cloud resources. Option C (incorrect) requires significant custom development and might not accurately reflect DynamoDB''s behavior. Option D (incorrect) involves migrating data and schema to a different database system, which is complex and introduces compatibility issues with the production DynamoDB setup.', 30, 'm_30_3', 4, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer is working on a complex AWS Lambda function that integrates with several AWS services. They want to test the Lambda function''s interactions with these services locally without deploying to AWS, using mock responses to simulate service behavior. Which approach is most effective for this scenario?', '["Deploy the Lambda function and all dependent services to a dedicated ''sandbox'' AWS account for testing.","Use AWS SAM CLI with integrated mocking capabilities for AWS services.","Implement a custom mocking framework within the Lambda code to intercept AWS SDK calls.","Utilize open-source tools like LocalStack or moto to simulate AWS services locally."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective approach for local testing of Lambda functions with mocked AWS service interactions. Tools like LocalStack and moto provide local emulators for various AWS services, allowing developers to run their Lambda functions locally and have them interact with these emulated services, closely mimicking the AWS environment without actual cloud deployments. Option A (incorrect) involves deploying to a cloud environment, incurring costs and slower feedback loops, which contradicts the goal of local testing. Option B (incorrect) AWS SAM CLI primarily focuses on Lambda and API Gateway emulation; while it can integrate with local mocks, it doesn''t natively provide comprehensive mocking for all AWS services. Option C (incorrect) requires significant custom development and maintenance, which adds overhead and might not cover all service behaviors accurately.', 30, 'm_30_3', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_30_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A company uses AWS CodePipeline to automate the deployment of its containerized application to Amazon ECS. They need to implement a deployment strategy that gradually shifts traffic to the new version while monitoring for errors, with an automatic rollback if issues are detected, to minimize impact on users. Which CodeDeploy deployment type should be used?', '["All-at-once deployment.","Rolling deployment.","Blue/green deployment.","In-place deployment."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable CodeDeploy deployment type for this scenario. Blue/green deployments for Amazon ECS allow a new version of the application to be deployed alongside the old version. Traffic is then gradually shifted to the new version, and if issues arise, traffic can be quickly rolled back to the stable old version, minimizing downtime and user impact (ap-3.3-001). Option A (incorrect) deploys the new version to all instances simultaneously, causing downtime if the new version fails. Option B (incorrect) updates instances in batches, which can still cause issues if a bad version is deployed. Option D (incorrect) is not a standard CodeDeploy deployment type for ECS, which typically uses blue/green.', 30, 'm_30_4', 6, NULL, NULL),
  ('mock_28_all_1775007111773', 'A development team is setting up a CI/CD pipeline for a serverless application using AWS CodePipeline. The pipeline needs to fetch source code from a Git repository, build the application, run tests, and deploy it. They want to ensure that the build process is fully automated and triggered by code changes. Which sequence of CodePipeline stages is appropriate?', '["Source → Deploy → Test → Build","Source → Build → Test → Deploy","Build → Source → Test → Deploy","Deploy → Source → Build → Test"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) represents the standard and logical flow for a CI/CD pipeline in AWS CodePipeline. First, the Source stage retrieves the code (e.g., from AWS CodeCommit). Next, the Build stage compiles the code and runs unit tests (e.g., using AWS CodeBuild). Then, the Test stage performs integration or acceptance tests. Finally, the Deploy stage deploys the application to the target environment (e.g., using AWS CodeDeploy or AWS SAM). The other options represent illogical or inefficient sequences for a CI/CD pipeline.', 30, 'm_30_4', 7, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer is configuring an AWS CodeBuild project to build a Java application. The build process requires a database connection string and an API key. These credentials must be kept secure and not exposed in plaintext in the build logs or configuration files. How should these sensitive values be managed?', '["Store them as plaintext environment variables directly in the CodeBuild project configuration.","Embed them directly into the source code and obfuscate them before committing.","Store them in AWS Secrets Manager or AWS Systems Manager Parameter Store (SecureString) and reference them in the buildspec.yml.","Pass them as command-line arguments to the build script during pipeline execution."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS best practice for managing sensitive credentials in CI/CD pipelines. AWS Secrets Manager and AWS Systems Manager Parameter Store (SecureString) provide secure, encrypted storage for secrets. These secrets can then be referenced in the buildspec.yml file, and CodeBuild will securely inject them as environment variables at runtime, preventing them from being exposed in plaintext in the console or logs (ap-3.4-001). Option A (incorrect) is an anti-pattern (ap-3.4-001) as plaintext environment variables are visible in the console and build logs. Option B (incorrect) is a severe security risk and makes secrets difficult to manage and rotate. Option D (incorrect) can expose secrets in command history or process listings, which is not secure.', 30, 'm_30_4', 8, NULL, NULL),
  ('mock_28_all_1775007111773', 'A company is deploying a critical AWS Lambda function to production. They want to introduce new versions with minimal risk, gradually shifting a small percentage of user traffic to the new version first, and automatically rolling back if any errors are detected. Which deployment mechanism should the developer use?', '["Update the Lambda function code directly, overwriting the existing version.","Use AWS CodeDeploy with an all-at-once deployment strategy for the Lambda function.","Implement Lambda alias routing with traffic shifting and CloudWatch alarms for automated rollback.","Manually deploy the new Lambda version and monitor logs for a few hours before switching DNS records."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the recommended approach for low-risk Lambda deployments. Lambda alias routing allows traffic to be shifted gradually (e.g., canary or linear deployments) between two Lambda function versions. By integrating with CloudWatch alarms, the system can automatically roll back to the previous stable version if error rates or other metrics exceed predefined thresholds, minimizing impact (ap-3.3-001). Option A (incorrect) is highly risky as it provides no rollback mechanism and immediately impacts all users. Option B (incorrect) is an anti-pattern (ap-3.3-001) for production Lambda updates as it causes downtime if the new version fails. Option D (incorrect) is a manual process, prone to human error, and does not provide automated rollback capabilities.', 30, 'm_30_4', 9, NULL, NULL),
  ('mock_28_all_1775007111773', 'A development team uses AWS CodeDeploy to deploy applications to Amazon EC2 instances. They need to define specific actions to be performed during different phases of the deployment lifecycle, such as installing dependencies before traffic is routed and running validation tests after traffic is shifted. Which file is used to specify these lifecycle hooks?', '["buildspec.yml","template.yaml","AppSpec file","Dockerfile"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS CodeDeploy AppSpec file. This YAML or JSON formatted file is used to manage a CodeDeploy deployment, specifying source files, permissions, and, crucially, lifecycle event hooks (e.g., BeforeInstall, AfterInstall, ApplicationStop, ApplicationStart, BeforeAllowTraffic, AfterAllowTraffic). These hooks allow developers to run scripts at specific points during the deployment process. Option A (incorrect) is used by AWS CodeBuild for defining build commands. Option B (incorrect) is used by AWS SAM for defining serverless applications. Option D (incorrect) is used for defining Docker container images.', 30, 'm_30_4', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_30_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A development team is building a microservice that runs as a Docker container. They need a secure and scalable way to store and manage their Docker images before deploying them to Amazon ECS or AWS Fargate. Which AWS service is purpose-built for this requirement?', '["Amazon S3 for storing container image files.","AWS CodeArtifact for managing software packages.","Amazon Elastic Container Registry (Amazon ECR) for Docker images.","AWS CodeCommit for version controlling Dockerfile and images."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the dedicated AWS service for storing and managing Docker container images. Amazon ECR is a fully managed Docker container registry that makes it easy for developers to store, manage, and deploy Docker container images. It integrates seamlessly with Amazon ECS, AWS Fargate, and AWS CodePipeline. Option A (incorrect) can store files, but it lacks the features of a dedicated container registry like image versioning, vulnerability scanning, and direct integration with container services. Option B (incorrect) is for managing software packages (e.g., Maven, npm, PyPI), not Docker images. Option D (incorrect) is a version control service for source code, not for storing compiled Docker images.', 30, 'm_30_1', 11, NULL, NULL),
  ('mock_28_all_1775007111773', 'A company is developing a serverless application consisting of AWS Lambda functions, Amazon API Gateway, and Amazon DynamoDB. They need a framework to define and deploy these resources as a single unit, using infrastructure as code, with simplified syntax for serverless components. Which AWS framework should they use?', '["AWS Cloud Development Kit (AWS CDK).","AWS Serverless Application Model (AWS SAM).","AWS CloudFormation directly.","AWS Elastic Beanstalk."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for defining and deploying serverless applications. AWS SAM extends AWS CloudFormation with a simplified syntax for serverless resources like AWS Lambda functions, Amazon API Gateway APIs, and Amazon DynamoDB tables, making it easier to manage and deploy serverless infrastructure as code. Option A (incorrect) is a general-purpose infrastructure as code framework that supports multiple programming languages, but SAM provides a more opinionated and simplified approach specifically for serverless. Option C (incorrect) can be used, but SAM provides a higher-level abstraction and simplified syntax for common serverless patterns, reducing boilerplate. Option D (incorrect) is a platform-as-a-service for web applications, not a framework for defining serverless infrastructure as code.', 30, 'm_30_1', 12, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer is preparing a new version of an AWS Lambda function for deployment. The deployment package currently includes large development dependencies and test files, leading to increased cold start times. What is the MOST effective way to optimize the Lambda deployment package size for faster cold starts?', '["Increase the allocated memory for the Lambda function.","Use Lambda layers to manage all dependencies.","Exclude development dependencies and test files from the production deployment artifact.","Store the deployment package in an Amazon S3 bucket in a different region."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly addresses the problem of large deployment packages. Including unnecessary development dependencies and test files significantly increases the size of the deployment artifact, which in turn increases cold start times (ap-3.1-001). By ensuring that only production-essential code and dependencies are included, the package size is minimized, leading to faster download and initialization. Option A (incorrect) can reduce cold start times by providing more CPU, but it doesn''t address the root cause of a large package and might increase costs. Option B (incorrect) is good for sharing common dependencies but doesn''t inherently reduce the overall size of the function''s active code or prevent unnecessary files from being packaged. Option D (incorrect) would likely increase cold start times due to cross-region network latency, making it less efficient.', 30, 'm_30_1', 13, NULL, NULL),
  ('mock_28_all_1775007111773', 'A small startup is deploying a web application to AWS. They need a fully managed platform that handles infrastructure provisioning, deployment, scaling, and monitoring automatically, allowing developers to focus solely on code. Which AWS service provides this level of automation and management?', '["Amazon EC2 with Auto Scaling groups and Elastic Load Balancing.","AWS CloudFormation for infrastructure as code.","AWS Elastic Beanstalk.","AWS Lambda with Amazon API Gateway."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is designed for this exact scenario. AWS Elastic Beanstalk is an easy-to-use service for deploying and scaling web applications and services developed with various programming languages. It handles the provisioning of underlying resources (EC2 instances, load balancers, Auto Scaling groups, etc.), deployment, and health monitoring, allowing developers to upload their code and let Elastic Beanstalk manage the rest, thus minimizing operational overhead. Option A (incorrect) requires manual configuration and management of multiple services. Option B (incorrect) is for defining infrastructure as code but doesn''t provide the fully managed deployment and scaling runtime. Option D (incorrect) is a serverless compute and API service, suitable for specific workloads, but not a general-purpose platform for traditional web applications with the same ''fully managed'' scope as Elastic Beanstalk.', 30, 'm_30_1', 14, NULL, NULL),
  ('mock_28_all_1775007111773', 'A development team wants to manage all their application''s AWS resources (EC2 instances, Amazon RDS databases, Amazon S3 buckets, etc.) using infrastructure as code. They need a declarative way to define these resources and ensure consistent deployments across environments. Which AWS service is best suited for this purpose?', '["AWS Systems Manager for resource configuration.","AWS CloudFormation for declarative infrastructure as code.","AWS OpsWorks for configuration management.","AWS Management Console for manual resource provisioning."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the foundational AWS service for defining and provisioning infrastructure as code. AWS CloudFormation allows developers to define their AWS resources in a declarative template, ensuring consistent and repeatable deployments across different environments (development, staging, production). Option A (incorrect) is primarily for operational tasks like patching, automation, and remote command execution, not for defining infrastructure. Option C (incorrect) is a configuration management service that uses Chef or Puppet, which is different from declarative infrastructure provisioning. Option D (incorrect) involves manual actions, which is error-prone and does not provide infrastructure as code capabilities.', 30, 'm_30_1', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_30_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A developer is building an API using Amazon API Gateway and AWS Lambda. They want to have separate development and production environments for their API, allowing them to test new features in isolation before releasing them to users. Which API Gateway feature should be used to achieve this?', '["Create separate API Gateway endpoints for each environment.","Use different AWS accounts for development and production.","Configure API Gateway stages for each environment.","Implement custom domain names for each environment."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the native API Gateway feature for managing different environments. API Gateway stages allow developers to deploy different versions of their API (e.g., ''dev'', ''test'', ''prod'') to separate endpoints, each with its own configuration, caching, throttling, and associated Lambda function aliases. This enables isolated testing and deployment without affecting other environments. Option A (incorrect) is less efficient as it would mean creating entirely separate API Gateway resources instead of leveraging stages. Option B (incorrect) is a valid architectural pattern for environment separation but is a broader solution than what''s needed for just API Gateway and Lambda and incurs more management overhead. Option D (incorrect) is for custom branding and routing, not for defining distinct deployment environments.', 30, 'm_30_2', 16, NULL, NULL),
  ('mock_28_all_1775007111773', 'A team is developing a serverless application and needs to perform end-to-end integration tests in an isolated, non-production AWS environment. They want to ensure that the entire application stack, including AWS Lambda functions and Amazon DynamoDB tables, is deployed and tested in a dedicated staging environment. Which approach is MOST appropriate?', '["Test directly against the production environment during off-peak hours.","Use AWS SAM CLI to run all integration tests locally.","Deploy the application stack to a dedicated staging AWS account using AWS CloudFormation or AWS SAM.","Mock all AWS services and external dependencies during integration testing."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best practice for end-to-end integration testing in an isolated environment. Deploying the full application stack to a dedicated staging AWS account ensures that the application behaves as it would in production, but without impacting live users or data. AWS CloudFormation or AWS SAM are ideal for automating the provisioning of these environments. Option A (incorrect) is an anti-pattern (ap-3.2-001) as testing against production risks data corruption and performance issues. Option B (incorrect) is for local unit/component testing, not full end-to-end integration testing against a cloud environment. Option D (incorrect) is suitable for unit testing or specific integration points but does not validate the entire deployed stack''s behavior in a realistic cloud environment.', 30, 'm_30_2', 17, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer is iterating rapidly on an AWS Lambda function. They need to quickly test different versions of the function with specific event payloads without modifying the production environment or deploying new functions for every test. Which Lambda feature should be utilized?', '["Create a new Lambda function for each test iteration.","Use Lambda versions and aliases to manage and test different code versions.","Modify the production Lambda function directly and revert changes after testing.","Deploy the Lambda function to an Amazon EC2 instance for local testing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most efficient way to manage and test different versions of an AWS Lambda function. Lambda versions allow developers to publish immutable snapshots of their function code and configuration. Lambda aliases can then point to specific versions, or even shift traffic between them, enabling safe testing of new code without affecting the production alias. Option A (incorrect) creates unnecessary overhead and resource duplication. Option C (incorrect) is a highly risky practice that can lead to production outages and data corruption. Option D (incorrect) is not how Lambda functions are typically tested; Lambda is a serverless compute service, not designed to run on EC2 for testing purposes.', 30, 'm_30_2', 18, NULL, NULL),
  ('mock_28_all_1775007111773', 'A development team is building a new feature for an existing application. They want to test the new feature''s integration with other services by mocking external API calls, ensuring that their unit and integration tests are fast and reliable without depending on external service availability. Which testing strategy should they adopt?', '["Perform all tests against the live external APIs in a staging environment.","Implement a robust retry mechanism for all external API calls.","Use mock API integrations to simulate external service responses.","Deploy a dedicated instance of each external service within their AWS account for testing."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the ideal strategy for ensuring fast and reliable integration tests that are independent of external service availability. Mock API integrations allow developers to simulate the responses of external services, enabling them to test their application''s logic without making actual network calls, which can be slow, unreliable, or incur costs. Option A (incorrect) makes tests dependent on external service availability and can be slow. Option B (incorrect) improves resilience but does not make tests faster or independent of external services. Option D (incorrect) is complex, costly, and often impractical for a large number of external services.', 30, 'm_30_2', 19, NULL, NULL),
  ('mock_28_all_1775007111773', 'A company needs to ensure that all new features for their web application are thoroughly tested in an environment that closely mirrors production, but without affecting live users. They require a dedicated, isolated environment for functional testing before deployment. Which approach best achieves this goal?', '["Perform functional tests directly on the production environment during low-traffic periods.","Create a separate development environment that shares the same database as production.","Establish a dedicated staging environment that is a replica of the production architecture.","Conduct all functional testing using local development tools and mock services."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best practice for ensuring thorough functional testing without impacting live users. A dedicated staging environment, which is a near-replica of the production architecture, allows for realistic testing of new features, performance, and integrations in an isolated manner. This minimizes the risk of introducing issues into production. Option A (incorrect) is highly risky and can lead to production outages or data corruption. Option B (incorrect) introduces a dependency on the production database, which can lead to data integrity issues and is not truly isolated. Option D (incorrect) is suitable for unit and component testing, but it cannot fully replicate the complexities and interactions of a production-like cloud environment for comprehensive functional testing.', 30, 'm_30_2', 20, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 20
WHERE id = 'mock_28_all_1775007111773';

COMMIT;

