-- Module: m_31_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A development team is building a new microservice that processes user requests. They need to capture detailed information about each request, including the `userId`, `transactionId`, and `requestLatency`, for debugging and analysis. This data has high cardinality. They want to store this information in a cost-effective way that allows for complex queries and aggregations later, with the LEAST impact on application performance.', '["Use structured logging with AWS Lambda Powertools and send logs to Amazon CloudWatch Logs, then use CloudWatch Logs Insights for analysis.","Create custom Amazon CloudWatch metrics with `userId` and `transactionId` as dimensions for each request.","Send all detailed request data as custom annotations to AWS X-Ray traces.","Store the detailed request data in an Amazon DynamoDB table for later querying and analysis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and efficient solution for high-cardinality data. Structured logging with AWS Lambda Powertools allows embedding detailed request information (`userId`, `transactionId`, `requestLatency`) into log events sent to Amazon CloudWatch Logs. CloudWatch Logs Insights can then be used to perform complex queries and aggregations on this data. This approach is cost-effective because CloudWatch Logs is optimized for high-volume log data and Logs Insights for querying, with minimal performance impact. Option B (incorrect) represents anti-pattern [ap-4.2-001]. Creating custom CloudWatch metrics with high-cardinality dimensions like `userId` or `transactionId` would lead to an explosion of unique metric combinations, resulting in enormous costs. Option C (incorrect) is not ideal because AWS X-Ray annotations have size limits and are primarily for tracing, not for high-volume, complex metric aggregation or querying like logs. Option D (incorrect) would add significant operational overhead and cost for writes and reads to a DynamoDB table, which is not designed for raw observability data storage and querying.', 31, 'm_31_2', 7, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer is instrumenting an AWS Lambda function to monitor its internal processing steps and external service calls. They want to capture a detailed timeline of execution, including subsegment durations and any errors, to understand the flow and identify bottlenecks. Which AWS service and SDK integration should be used for this purpose?', '["Utilize Amazon CloudWatch Embedded Metrics Format (EMF) to emit custom metrics for each processing step.","Implement structured logging to Amazon CloudWatch Logs for each internal processing step and external call.","Create custom Amazon CloudWatch alarms on the Lambda function''s duration and error rates.","Integrate the AWS X-Ray SDK into the Lambda function code to record traces and subsegments."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the appropriate choice. Integrating the AWS X-Ray SDK into the Lambda function allows the developer to record traces and subsegments, providing a detailed timeline of execution, including internal processing steps and external service calls. X-Ray visualizes this data, making it easy to identify bottlenecks and errors within the function''s execution flow. Option A (incorrect) focuses on metrics, which are aggregated numerical data, not detailed timelines or traces. Option B (incorrect) provides log data, which can be useful for debugging, but it doesn''t offer the visual timeline and service map capabilities of X-Ray for understanding the flow. Option C (incorrect) sets up alarms for alerting, which is a reactive measure, not an instrumentation method for detailed timeline capture.', 31, 'm_31_2', 8, NULL, NULL),
  ('mock_28_all_1775007111773', 'A company needs to monitor the number of successful and failed transactions processed by an AWS Lambda function. They want to create custom metrics that can be easily visualized in Amazon CloudWatch dashboards and trigger alarms. The solution should be simple to implement and maintain.', '["Use AWS X-Ray to trace each transaction and count successes/failures from the trace data.","Emit custom Amazon CloudWatch metrics from the Lambda function code using the AWS SDK.","Parse Amazon CloudWatch Logs for ''SUCCESS'' and ''FAILURE'' strings and create CloudWatch metric filters.","Implement Amazon CloudWatch Embedded Metrics Format (EMF) for each transaction, embedding success/failure status."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the simplest and most direct way to achieve this. Emitting custom Amazon CloudWatch metrics directly from the Lambda function code using the AWS SDK allows for straightforward visualization in CloudWatch dashboards and easy configuration of alarms. This is ideal for low-cardinality, aggregate metrics like success/failure counts. Option A (incorrect) uses AWS X-Ray, which is primarily for distributed tracing and not the most efficient or direct way to aggregate simple success/failure counts for metrics. Option C (incorrect) involves creating metric filters, which can work but adds more complexity and relies on specific log formats, making it less robust than direct custom metrics. Option D (incorrect) is powerful for high-cardinality metrics but is overkill for simple success/failure counts, adding unnecessary complexity compared to direct custom metrics.', 31, 'm_31_2', 9, NULL, NULL),
  ('mock_28_all_1775007111773', 'A development team is building a new application with several AWS Lambda functions interacting with Amazon DynamoDB. They want to ensure consistent logging, tracing, and metric emission across all functions without writing extensive boilerplate code. Which AWS library is specifically designed to simplify this instrumentation for Lambda functions?', '["AWS Lambda Powertools","AWS X-Ray SDK","Standard AWS SDK for Python/Node.js","Amazon CloudWatch Agent"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for this purpose. AWS Lambda Powertools is a suite of utilities for AWS Lambda functions that provides structured logging, custom metrics (using CloudWatch EMF), and distributed tracing (with X-Ray) with minimal boilerplate code. It promotes best practices for observability in serverless applications. Option B (incorrect) is primarily focused on distributed tracing and does not provide comprehensive utilities for logging and metrics. Option C (incorrect) is the foundational SDK but requires developers to implement logging, metrics, and tracing logic manually, which is what Powertools aims to simplify. Option D (incorrect) is used for collecting metrics and logs from EC2 instances or on-premises servers, not for instrumenting Lambda function code.', 31, 'm_31_2', 10, NULL, NULL),
  ('mock_28_all_1775007111773', 'A serverless application processes millions of events daily, each associated with a unique `customer_id`. The operations team needs to monitor the total number of events processed and the average processing duration per `customer_id` for specific customers, but they are concerned about the cost of creating a separate CloudWatch metric for each customer. Which approach is MOST cost-effective for capturing these high-cardinality metrics?', '["Create a custom Amazon CloudWatch metric for each `customer_id` with `customer_id` as a dimension.","Send `customer_id` and processing duration as custom annotations to AWS X-Ray traces.","Use Amazon CloudWatch Embedded Metrics Format (EMF) to embed metrics within structured log events, then use CloudWatch Logs Insights for querying.","Log all event details, including `customer_id` and duration, to Amazon CloudWatch Logs and rely solely on CloudWatch Logs Insights for all analysis."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the MOST cost-effective approach for high-cardinality metrics. CloudWatch Embedded Metrics Format (EMF) allows embedding custom metrics within structured log events, which are then sent to CloudWatch Logs. This avoids the cost explosion of creating individual CloudWatch metrics for each unique `customer_id` (anti-pattern [ap-4.2-001]). CloudWatch Logs Insights can then efficiently query and aggregate these embedded metrics, providing the required analysis without incurring per-metric costs for high-cardinality dimensions. Option A (incorrect) represents anti-pattern [ap-4.2-001] directly; creating a separate CloudWatch metric for each unique `customer_id` would be prohibitively expensive due to the high cardinality. Option B (incorrect) uses X-Ray, which is for tracing individual requests, not for aggregating high-volume metrics efficiently. Option D (incorrect) is a valid approach for general log analysis, but EMF specifically streamlines the process of extracting and visualizing metrics from logs, making it more efficient for structured metric data.', 31, 'm_31_2', 11, NULL, NULL),
  ('mock_28_all_1775007111773', 'A developer wants to add custom metadata, such as a `deployment_id` and `feature_flag_status`, to AWS X-Ray traces generated by an AWS Lambda function. This metadata should be easily searchable and viewable within the X-Ray console for debugging specific deployments. Which X-Ray feature should the developer use?', '["Emit custom Amazon CloudWatch metrics with `deployment_id` as a dimension.","Use X-Ray annotations or metadata within the AWS X-Ray SDK to add key-value pairs to traces.","Include the metadata in Amazon CloudWatch Logs as part of structured log entries.","Configure Amazon API Gateway access logs to capture custom headers containing this metadata."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the direct and intended way to add searchable metadata to AWS X-Ray traces. The AWS X-Ray SDK provides methods to add annotations (indexed for filtering) and metadata (not indexed, but viewable) to traces and subsegments. This allows developers to attach contextual information like `deployment_id` or `feature_flag_status` that can be used to filter and analyze traces directly within the X-Ray console. Option A (incorrect) uses CloudWatch metrics, which are for aggregated numerical data, not for attaching specific metadata to individual traces. Option C (incorrect) sends data to CloudWatch Logs, which is separate from X-Ray traces and not directly searchable within the X-Ray console. Option D (incorrect) captures data at the API Gateway level, but it wouldn''t be part of the X-Ray trace generated by the Lambda function itself.', 31, 'm_31_2', 12, NULL, NULL),
  ('mock_28_all_1775007111773', 'A new serverless application needs to emit several application-specific metrics (e.g., `items_processed`, `failed_items`) from an AWS Lambda function. These metrics should be easily consumable by Amazon CloudWatch for dashboarding and alarming, without requiring complex parsing of log files. The development team wants to use a simple and efficient method.', '["Use Amazon CloudWatch Embedded Metrics Format (EMF) to embed custom metrics within structured log events.","Write custom code to publish each metric individually using the `PutMetricData` API call via the AWS SDK.","Rely solely on AWS X-Ray traces to derive these metrics by analyzing trace data.","Create Amazon CloudWatch Logs metric filters to extract metrics from unstructured log lines."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is a simple and efficient method for emitting application-specific metrics. CloudWatch Embedded Metrics Format (EMF) allows developers to embed custom metrics within structured log events. These logs are then sent to Amazon CloudWatch Logs, and CloudWatch automatically extracts the embedded metrics, making them easily consumable for dashboards and alarms without complex log parsing. Option B (incorrect) involves more verbose custom code and potentially more API calls, making it less efficient than EMF for multiple metrics. Option C (incorrect) uses AWS X-Ray, which is primarily for distributed tracing and not the main mechanism for emitting application-specific business metrics. Option D (incorrect) requires defining metric filters and specific log formats, which can be less robust and more complex than EMF for structured metric emission.', 31, 'm_31_2', 13, NULL, NULL),
  ('mock_28_all_1775007111773', 'A serverless application processes millions of user requests daily through AWS Lambda functions. The development team needs to monitor individual user request latency and error rates to identify specific users experiencing issues, without incurring excessive CloudWatch costs or increasing operational overhead.', '["Instrument Lambda functions to emit custom Amazon CloudWatch metrics for each user ID, tracking latency and errors as dimensions.","Use AWS X-Ray SDK to add annotations for each user ID to traces, then filter traces by user ID in the X-Ray console.","Implement AWS Lambda Powertools for Python to enable structured logging with user ID in log events, then use CloudWatch Logs Insights for analysis.","Set up an Amazon EC2 instance to collect and parse raw Lambda logs, then store aggregated user-specific metrics in a custom database."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) utilizes AWS Lambda Powertools for Python, which simplifies structured logging. By including the user ID in structured log events, the team can then use CloudWatch Logs Insights to efficiently query and analyze individual user request latency and error rates. This approach is cost-effective because it avoids creating high-cardinality metrics, and CloudWatch Logs Insights is designed for efficient analysis of log data.
Option A (incorrect) proposes emitting custom Amazon CloudWatch metrics with user ID as a dimension. This approach directly violates anti-pattern [ap-4.2-001], which warns against putting high-cardinality data (like millions of unique user IDs) in CloudWatch metric dimensions. Each unique dimension combination creates a distinct metric, leading to enormous costs and making the solution impractical for millions of users.
Option B (incorrect) suggests using AWS X-Ray annotations for each user ID. While X-Ray provides excellent distributed tracing, adding an annotation for every single user ID in a high-volume application can significantly increase X-Ray costs and is not the most efficient way to get aggregate statistics or filter for individual user performance at scale compared to structured logging and Logs Insights.
Option D (incorrect) involves setting up and managing an Amazon EC2 instance for log collection and parsing. This introduces significant operational overhead, including server management, scaling, and maintenance, which contradicts the goal of avoiding increased operational overhead for a serverless application.', 31, 'm_31_2', 14, NULL, NULL);

