INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_28_all_1775007111773', 'A public-facing API built with Amazon API Gateway and AWS Lambda serves static content that changes infrequently. The application experiences high request volumes, leading to increased Lambda invocation costs and higher latency. The development team needs to reduce latency and cost for these frequently accessed, rarely changed endpoints with the LEAST operational overhead.', '["Implement an Amazon ElastiCache for Redis cluster and integrate it into the Lambda function code to cache responses.","Enable API Gateway caching for the relevant API endpoints with an appropriate Time To Live (TTL).","Configure Amazon CloudFront in front of the API Gateway to cache content at edge locations globally.","Increase the memory allocated to the AWS Lambda function to improve its execution performance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution for reducing latency and cost with the LEAST operational overhead for frequently accessed, rarely changed static content. API Gateway caching is a fully managed feature that caches responses directly at the API Gateway layer, significantly reducing the number of backend AWS Lambda invocations and improving response times. Option A (incorrect) would introduce an Amazon ElastiCache cluster, which requires more operational overhead for deployment, management, and integration into the Lambda function code. Option C (incorrect) is effective for global content distribution but might be overkill for a regional API and introduces additional configuration compared to the direct API Gateway caching. Option D (incorrect) addresses Lambda performance but does not reduce the number of invocations or provide a caching layer for repeated requests, representing anti-pattern [ap-4.3-001].', 31, 'm_31_3', 15, NULL, NULL),
  ('mock_28_all_1775007111773', 'An AWS Lambda function processes messages from an Amazon SQS queue. The function is invoked for each message, but the processing logic is designed to handle multiple messages efficiently in a single batch. The development team wants to optimize costs and reduce the number of Lambda invocations. Which SQS-Lambda integration feature should they use?', '["Configure the Amazon SQS event source mapping for the Lambda function with a batch size greater than 1.","Increase the memory allocated to the AWS Lambda function to improve its processing speed.","Implement a custom polling mechanism within the Lambda function to pull multiple messages from the SQS queue.","Use AWS Step Functions to orchestrate multiple Lambda invocations for batch processing."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and native way to optimize costs and reduce Lambda invocations when processing SQS messages in batches. By configuring the SQS event source mapping with a batch size greater than 1, Lambda will invoke the function with a batch of messages, reducing the total number of invocations and leveraging the function''s ability to process multiple messages efficiently. Option B (incorrect) improves the performance of individual invocations but does not reduce the total number of invocations. Option C (incorrect) adds unnecessary complexity and operational overhead by requiring custom polling logic within the Lambda function, duplicating functionality already provided by the event source mapping. Option D (incorrect) introduces an orchestration service, which adds complexity and cost, and is not the primary mechanism for optimizing SQS batch processing with Lambda.', 31, 'm_31_3', 16, NULL, NULL),
  ('mock_28_all_1775007111773', 'A backend service uses AWS Lambda functions to perform complex data transformations. These transformations are CPU-intensive, and the current Lambda configuration leads to high execution durations and costs. The development team needs to optimize the function''s performance and cost-efficiency. Which Lambda setting should they adjust FIRST?', '["Increase the function''s timeout setting to prevent premature termination.","Implement provisioned concurrency for the function to reduce cold starts.","Tune the Lambda function''s memory allocation to automatically scale CPU resources.","Re-architect the application to use Amazon EC2 instances instead of Lambda for heavy processing."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective first step for optimizing CPU-intensive Lambda functions. In AWS Lambda, CPU resources are allocated proportionally to the memory configured for the function. Increasing the memory allocation also increases the available CPU power, which can significantly reduce the execution duration and, consequently, the cost for CPU-bound tasks. Option A (incorrect) only prevents timeouts but does not improve the actual performance or cost-efficiency of the function. Option B (incorrect) reduces cold start latency but does not directly optimize the execution duration of an already running, CPU-intensive task. Option D (incorrect) is a drastic architectural change that introduces significant operational overhead and complexity, rather than an optimization within the existing Lambda architecture.', 31, 'm_31_3', 17, NULL, NULL),
  ('mock_28_all_1775007111773', 'A mobile application frequently reads data from an Amazon DynamoDB table. To improve response times and reduce the load on the DynamoDB table, the development team wants to implement a caching layer. The solution should be fully managed and provide microsecond latency for cached items.', '["Implement Amazon DynamoDB Accelerator (DAX) in front of the DynamoDB table.","Set up an Amazon ElastiCache for Memcached cluster and integrate it into the application logic.","Use Amazon API Gateway caching for the API endpoints that query DynamoDB.","Implement client-side caching within the mobile application to store frequently accessed data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. Amazon DynamoDB Accelerator (DAX) is a fully managed, highly available, in-memory cache for DynamoDB that delivers microsecond response times for frequently accessed data. It is specifically designed to work with DynamoDB, reducing the load on the table and improving application performance with minimal code changes. Option B (incorrect) involves setting up and managing an Amazon ElastiCache cluster, which adds operational overhead and requires more complex application-level integration compared to DAX. Option C (incorrect) only caches responses at the API Gateway level and might not provide the microsecond latency or direct DynamoDB load reduction needed for all read patterns. Option D (incorrect) helps individual clients but does not reduce the load on the DynamoDB table for all users or provide a shared caching layer.', 31, 'm_31_3', 18, NULL, NULL),
  ('mock_28_all_1775007111773', 'A web application experiences high traffic spikes, leading to occasional "cold starts" for its backend AWS Lambda functions, resulting in increased latency for users. The application requires consistently low latency, even during periods of inactivity. Which Lambda feature should be enabled to address this issue MOST effectively?', '["Increase the memory allocation for the AWS Lambda functions to speed up initialization.","Implement Amazon API Gateway caching for the API endpoints to serve cached responses.","Use a warm-up script to periodically invoke the Lambda functions and keep them active.","Configure Provisioned Concurrency for the critical AWS Lambda functions."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the MOST effective solution for addressing cold starts and ensuring consistently low latency for AWS Lambda functions. Provisioned Concurrency keeps a specified number of execution environments initialized and ready to respond immediately to invocations, eliminating cold starts. Option A (incorrect) can improve the execution speed of a function but does not directly eliminate cold starts. Option B (incorrect) only caches responses for repeated identical requests and does not prevent cold starts for uncached or dynamic requests. Option C (incorrect) is a manual and less reliable approach compared to Provisioned Concurrency, which is a native and fully managed feature designed for this exact problem.', 31, 'm_31_3', 19, NULL, NULL),
  ('mock_28_all_1775007111773', 'A public-facing REST API, built with Amazon API Gateway and AWS Lambda, serves product catalog data. The data changes infrequently (once a day), but the API receives millions of read requests per hour. This leads to high AWS Lambda invocation costs and increased latency for users. The team needs to reduce costs and improve response times for read operations with the LEAST architectural change.', '["Increase the provisioned concurrency for the AWS Lambda function to reduce cold starts and improve response times.","Enable API Gateway caching for the relevant API methods with an appropriate Time-To-Live (TTL) value.","Implement Amazon CloudFront in front of the API Gateway to cache responses globally and reduce origin load.","Integrate an Amazon ElastiCache for Redis cluster between AWS Lambda and Amazon DynamoDB to cache product data."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution. Enabling API Gateway caching for the relevant API methods with an appropriate Time-To-Live (TTL) directly addresses the problem. Since the product catalog data changes infrequently, API Gateway can serve cached responses for millions of requests without invoking the backend AWS Lambda function, drastically reducing Lambda costs and improving response times. This is the LEAST architectural change as it''s a built-in feature of API Gateway, and it directly addresses anti-pattern [ap-4.3-001].
Option A (incorrect) would reduce cold starts and improve latency for Lambda, but it would not reduce the number of Lambda invocations for frequently accessed, rarely changed data. This means it would not significantly reduce costs, which is a primary constraint.
Option C (incorrect) suggests implementing Amazon CloudFront. While CloudFront is excellent for global content distribution and caching, for an API Gateway endpoint, enabling API Gateway''s native caching is a more direct and often simpler solution for caching API responses, especially when the primary goal is to reduce backend invocations and latency at the API layer with the LEAST architectural change. CloudFront would add another layer of complexity.
Option D (incorrect) involves integrating an Amazon ElastiCache for Redis cluster. This is a valid caching strategy but introduces significant architectural changes, including managing an ElastiCache cluster, modifying Lambda code to interact with ElastiCache, and handling cache invalidation logic. This approach has higher operational overhead and complexity compared to simply enabling API Gateway''s built-in caching for this specific scenario.', 31, 'm_31_3', 20, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 20
WHERE id = 'mock_28_all_1775007111773';

